#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET     2          /* BCM 2 */
#define POLL_INTERVAL   5          /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM 2 */
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output control of the line */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output.\n", LINE_OFFSET);

    while (g_running) {
        int value = rand() % 2;      /* 0 or 1 — within valid range */

        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            break;
        }

        printf("Value written to GPIO %d: %d\n", LINE_OFFSET, value);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// Register addresses
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

// Config register bits
#define CONFIG_OS_BEGIN   (1 << 15)
#define CONFIG_MUX_AIN0   (0x4000) // AIN0 vs GND
#define CONFIG_PGA_4_096V (0x0200) // +/-4.096V range
#define CONFIG_MODE_SS    (0x0100) // Single-shot mode
#define CONFIG_DR_128SPS  (0x0080) // 128 SPS
#define CONFIG_CQUE_NONE  (0x0003) // Disable comparator

static volatile sig_atomic_t running = 1;

void int_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Starting ADS1115 sampling...\n");

    while (running) {
        // Start single conversion on AIN0
        uint16_t config = CONFIG_OS_BEGIN | CONFIG_MUX_AIN0 |
                          CONFIG_PGA_4_096V | CONFIG_MODE_SS |
                          CONFIG_DR_128SPS | CONFIG_CQUE_NONE;

        if (i2c_write_reg16(fd, REG_CONFIG, config) < 0) {
            fprintf(stderr, "Error writing config\n");
            break;
        }

        // Wait for conversion to complete (~8ms for 128 SPS)
        usleep(10000);

        uint16_t raw;
        if (i2c_read_reg16(fd, REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Error reading conversion\n");
            break;
        }

        // Convert to signed 16-bit and apply PGA gain
        int16_t val = (int16_t)raw;
        double voltage = val * 4.096 / 32768.0; // +/-4.096V range

        printf("AIN0: %.4f V\n", voltage);
        fflush(stdout);

        sleep(1);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Optional: probe by trying a read of the EEPROM ROM ID register */
    uint8_t reg = 0x2400;
    ssize_t w = write(fd, &reg, 1);
    if (w != 1) {
        fprintf(stderr, "MLX90614 not responding at 0x%02X: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        /* Read two bytes starting at the TOBJ1 temperature register (0x0B) */
        uint8_t cmd[1] = {0x0B};
        if (write(fd, cmd, 1) != 1) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            break;
        }
        usleep(10000);

        uint8_t buf[3];
        ssize_t n = read(fd, buf, 3);
        if (n != 3) {
            fprintf(stderr, "I2C read failed: got %zd bytes (%s)\n",
                    n, n < 0 ? strerror(errno) : "short read");
            break;
        }

        /* buf[0..1] = raw 16-bit value, buf[2] = CRC (ignored here) */
        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];

        /*
         * Raw conversion formula per datasheet:
         *   T_obj_C = -40 + (raw * 0.02)
         * But the MLX90614 returns data in units of 0.02 K.
         */
        float temp_celsius = -40.0f + (float)raw * 0.02f;
        printf("Temperature: %.2f °C\n", temp_celsius);
        fflush(stdout);

        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

