    }

    if (gpiod_line_set_value(line18, 1) < 0) {
        fprintf(stderr, "Failed to set line %d HIGH: %s\n",
                LINE_OFFSET_18, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d set to HIGH.\n", LINE_OFFSET_17, LINE_OFFSET_18);

    /* Wait for signals before exiting cleanly */
    while (!g_interrupted) {
        pause();
    }

    printf("\nInterrupt received, cleaning up...\n");
    rc = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN      18          /* BCM pin number */
#define PWM_FREQ_HZ  1000        /* 1 kHz carrier   */
#define DUTY_CYCLE   200         /* 20 % of range  */
#define PERIOD_US    500000      /* 0.5 s period   */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    /*
     * Set up the PWM channel.
     * gpioSetPWMfrequency returns the actual frequency used; we accept it.
     */
    unsigned freq = gpioSetPWMfrequency(PWM_PIN, PWM_FREQ_HZ);
    if (freq == 0) {
        fprintf(stderr, "Error: cannot set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("PWM initialised on GPIO %d at %u Hz (%s)\n",
           PWM_PIN, freq, (freq == PWM_FREQ_HZ) ? "ok" : "rounded");

    while (g_running) {
        rc = gpioPWM(PWM_PIN, DUTY_CYCLE);
        if (rc < 0) {
            fprintf(stderr, "Warning: gpioPWM returned %d\n", rc);
        } else {
            printf("GPIO %d PWM duty=%d\n", PWM_PIN, DUTY_CYCLE);
        }
        fflush(stdout);

        /*
         * Sleep in small increments so signals are caught promptly.
         */
        for (int i = 0; i < 50 && g_running; ++i) {
            usleep(10000);                 /* 10 ms */
        }
    }

    /* Clean shutdown: silence the line first, then release pigpio. */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <stdbool.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CHIP_NAME   "gpiochip0"
#define MAX_DISTANCE_CM 400.0f
#define MIN_DISTANCE_CM 2.0f

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / out-of-range / error.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(5);

    /* 10 us pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "set trigger high failed: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low after pulse failed: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout ~3 ms) */
    int val;
    long waited_us = 0;
    const long step = 100;
    while ((val = gpiod_line_get_value(echo)) == 0) {
        if (val < 0) {
            fprintf(stderr, "read echo low failed: %s\n", strerror(errno));
            return -1.0f;
        }
        usleep(step);
        waited_us += step;
        if (waited_us > 3000) {
            fprintf(stderr, "Timeout waiting for echo start.\n");
            return -1.0f;
        }
    }

    /* Measure echo high duration (timeout ~38 ms max round-trip @3V) */
    long elapsed_us = 0;
    long target_us = 38000;
    bool saw_high = false;
    while (!saw_high && elapsed_us < target_us) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "read echo high failed: %s\n", strerror(errno));
            return -1.0f;
        }
        if (val == 1) {
            saw_high = true;
        } else {
            usleep(step);
            elapsed_us += step;
        }
    }
    if (!saw_high) {
        fprintf(stderr, "Echo stuck low — sensor may be absent or disconnected.\n");
        return -1.0f;
    }

    /* Speed of sound ~343 m/s => 0.0343 cm/us; round trip => divide by 2 */
    float elapsed_s = (float)elapsed_us / 1000000.0f;
    float distance = elapsed_s * 34300.0f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of valid range [%.0f-%.0f].\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }
    return distance;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get line %d: %s\n", TRIGGER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get line %d: %s\n", ECHO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request trigger as output, initial value 0 */
    if (gpiod_line_request_output(trig, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Request trigger line as output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Request echo line as input failed: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ready on BCM pins %d (trigger) and %d (echo).\n", TRIGGER_PIN, ECHO_PIN);
    fflush(stdout);

    while (running) {
        float dist = measure_distance(trig, echo);
        if (dist < 0.0f) {
            fprintf(stderr, "Measurement failed; continuing next cycle.\n");
        } else {
            printf("Distance: %.2f cm\n", dist);
            fflush(stdout);
        }

        /* Sleep 60 s but wake early on signal */
        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    /* Clean release */
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28

/* Register addresses */
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

/*
 * Config word:
 *   OS=1 (start single conversion)
 *   MUX=100 (AIN0 vs GND) | PGA=000 (+/-4.096V) | MODE=1 (single-shot)
 *   DR=100 (128 SPS) | COMP_MODE=0 | COMP_POL=0 | COMP_LAT=0 | COMP_QUE=11
 * => 0xC3E3 = 0b1100001111100011
 */
#define CONFIG_VALUE   0xC3E3

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2];

    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "i2c write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Small delay so the device has time to clock out data */
    usleep(1000);

    ssize_t n = read(fd, rbuf, sizeof(rbuf));
    if (n != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "i2c read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Probe: try a config write with no payload to detect a NACK.
     * A real probe would be `read` after `write`, but this suffices
     * as a presence check before we start sampling.
     */
    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X.\n", ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) < 0) {
            break;
        }

        /* Wait for the conversion to complete (~8 ms @ 128 SPS) */
        usleep(10000);

        uint16_t raw;
        if (i2c_read_reg16(fd, REG_CONVERSION, &raw) < 0) {
            break;
        }

        /* Check bit 15 of the result for overflow */
        if (raw & 0x8000) {
            fprintf(stderr, "Warning: conversion overflow (0x%04X)\n", raw);
        } else {
            printf("%u\n", raw);
            fflush(stdout);
        }

        /* Sleep ~5 s in 100 ms slices so SIGINT is responsive */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    if (close(fd) < 0) {
        perror("close");
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_OFFSET 18

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 18 */
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output access to the line */
    ret = gpiod_line_request_output(line, "digital_out", 0);
    if (ret != 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d configured as output.\n", LINE_OFFSET);

    while (keep_running) {
        /* Toggle the value each iteration */
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret != 0) {
            fprintf(stderr, "Error writing to line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            break;
        }

        printf("Output set to: %d\n", val);
        fflush(stdout);

        sleep(1);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CONSUMER "gpio-toggle"
#define CHIP_NAME "gpiochip0"
#define LINE_OFFSET 18

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Starting 3-cycle toggle sequence on GPIO %d...\n", LINE_OFFSET);

    for (int i = 0; i < 3 && keep_running; i++) {
        int val = i % 2 ? 1 : 0;
        if (gpiod_line_set_value(line, val) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, LINE_OFFSET, val);
        fflush(stdout);

        /* Sleep 2 s but wake early on signal */
        for (int ms = 0; ms < 2000 && keep_running; ms += 100)
            usleep(100000);
    }

    if (!keep_running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("Sequence complete.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// Register addresses
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

// Config register bits
#define CONFIG_OS_BEGIN   (1 << 15)
#define CONFIG_MUX_AIN0   (0x4000) // AIN0 vs GND
#define CONFIG_PGA_4_096V (0x0200) // +/-4.096V range
#define CONFIG_MODE_SS    (0x0100) // Single-shot mode
#define CONFIG_DR_128SPS  (0x0080) // 128 SPS
#define CONFIG_CQUE_NONE  (0x0003) // Disable comparator

static volatile sig_atomic_t running = 1;

void int_handler(int signum) {
    (void)signum;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("i2c_write_reg16: write failed");
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg addr failed");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read data failed");
        return -1;
    }

    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    int fd;
    uint16_t config_value;
    uint16_t conversion_result;
    int result;

    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Build configuration value
    config_value = CONFIG_OS_BEGIN | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V |
                   CONFIG_MODE_SS | CONFIG_DR_128SPS | CONFIG_CQUE_NONE;

    // Write configuration to ADS1115
    if (i2c_write_reg16(fd, REG_CONFIG, config_value) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Wait for conversion to complete (approx 7.5ms for 128 SPS)
    usleep(10000);

    // Read conversion result
    result = i2c_read_reg16(fd, REG_CONVERSION, &conversion_result);
    if (result < 0) {
        fprintf(stderr, "Error reading conversion result from ADS1115\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADS1115 Reading: %u\n", conversion_result);

    // Clean up
    close(fd);
    return EXIT_SUCCESS;
}

