    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", LINE_OFFSET_1, LINE_OFFSET_2);

    while (keep_running) {
        static int val1 = 0;
        static int val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_2, strerror(errno));
            goto cleanup;
        }

        printf("Line %d: %d | Line %d: %d\n", LINE_OFFSET_1, val1,
               LINE_OFFSET_2, val2);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define CMD_MEASURE_RH     0xE5
#define CMD_MEASURE_TEMP   0xE3
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo) {
    (void)signo;
    g_running = 0;
}

/* Read `len` bytes from the SI7021 into buf after issuing command `cmd`. */
static int si7021_read_cmd(int fd, uint8_t cmd, uint8_t *buf, size_t len) {
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) return -1;

    /* Datasheet: max conversion time ~12 ms for RH, ~6.5 ms for T. */
    usleep(15000);

    ssize_t r = read(fd, buf, len);
    if (r < 0 || (size_t)r != len) return -1;
    return 0;
}

static float raw_to_rh(uint16_t raw) {
    return ((125.0f * (float)raw) / 65536.0f) - 6.0f;
}

static float raw_to_celsius(uint16_t raw) {
    return ((175.72f * (float)raw) / 65536.0f) - 46.85f;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint8_t rh_raw[2];
        uint8_t t_raw[2];

        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (si7021_read_cmd(fd, CMD_MEASURE_RH, rh_raw, 2) == 0 &&
                si7021_read_cmd(fd, CMD_MEASURE_TEMP, t_raw, 2) == 0) {
                ok = 1;
                break;
            }
            usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts.\n", MAX_RETRIES);
            close(fd);
            return EXIT_FAILURE;
        }

        uint16_t rh_u = ((uint16_t)rh_raw[0] << 8) | rh_raw[1];
        uint16_t t_u  = ((uint16_t)t_raw[0] << 8)  | t_raw[1];

        float rh = raw_to_rh(rh_u);
        float c  = raw_to_celsius(t_u);

        if (rh < 0.0f || rh > 100.0f) {
            fprintf(stderr, "RH out of range: %.2f%%\n", rh);
            close(fd);
            return EXIT_FAILURE;
        }
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", c, rh);
        fflush(stdout);

        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* Register addresses */
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

/*
 * Config word:
 *   OS=1 (start single conversion)
 *   MUX=100 (AIN0 vs GND) | PGA=000 (+/-4.096V) | MODE=1 (single-shot)
 *   DR=100 (128 SPS) | COMP_MODE=0 | COMP_POL=0 | COMP_LAT=0 | COMP_QUE=11
 * => 0xC183
 */
#define CONFIG_VALUE   0xC183

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo) {
    (void)signo;
    g_stop = 1;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADS1115 slave address */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Trigger a single-shot conversion.
     * i2c_smbus_write_word_data sends data in little-endian format,
     * which matches the ADS1115 register layout.
     */
    __u16 config_le = (__u16)CONFIG_VALUE;
    if (i2c_smbus_write_word_data(fd, REG_CONFIG, config_le) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Wait for the conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    /* Read the conversion result (two bytes, big-endian on the wire) */
    __s16 raw = i2c_smbus_read_word_data(fd, REG_CONVERSION);
    if (raw < 0) {
        fprintf(stderr, "Error reading conversion register: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Convert to signed 16-bit and print */
    printf("Raw ADC value: %d\n", (int16_t)raw);
    fflush(stdout);

    /* Sleep 1 s before next sample */
    sleep(1);

    /* Second reading */
    if (i2c_smbus_write_word_data(fd, REG_CONFIG, config_le) < 0) {
        fprintf(stderr, "Error re-triggering config: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10000);
    raw = i2c_smbus_read_word_data(fd, REG_CONVERSION);
    if (raw < 0) {
        fprintf(stderr, "Error reading conversion: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Raw ADC value: %d\n", (int16_t)raw);
    fflush(stdout);
    sleep(1);

    /* Third and final reading */
    if (i2c_smbus_write_word_data(fd, REG_CONFIG, config_le) < 0) {
        fprintf(stderr, "Error re-triggering config: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10000);
    raw = i2c_smbus_read_word_data(fd, REG_CONVERSION);
    if (raw < 0) {
        fprintf(stderr, "Error reading conversion: %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Raw ADC value: %d\n", (int16_t)raw);
    fflush(stdout);

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_PINS 6
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* Install signal handlers so Ctrl-C releases the chip cleanly */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip that exposes BCM GPIOs on the Pi */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as an output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "blink", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting blink pattern on BCM GPIO 8,9,10,11,23,24...\n");

    srand((unsigned int)time(NULL));

    for (int cycle = 0; cycle < 256 && keep_running; cycle++) {
        for (int i = 0; i < NUM_PINS; i++)
            vals[i] = rand() & 1;

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                fprintf(stderr, "Error setting value on pin %u: %s\n",
                        pins[i], strerror(errno));
                goto cleanup;
            }
        }

        usleep(100000); /* 100 ms */
    }

    if (!keep_running)
        printf("\nInterrupted by signal.\n");

    ret = EXIT_SUCCESS;

cleanup:
    /* Release any successfully requested lines */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

