#include <unistd.h>
#include <gpiod.h>

#define OUTPUT_PIN 17

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!line) {
        perror("Failed to get GPIO line 17");
        goto cleanup;
    }

    /* Request the line as output, initially low */
    if (gpiod_line_request_output(line, "output-example", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    /* Toggle the pin: HIGH then LOW */
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO value HIGH");
        goto cleanup;
    }
