            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }

        val = !val;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            fprintf(stderr, "Error writing to line: %s\n", strerror(errno));
            break;
        }

        printf("Output set to: %d\n", val);
        fflush(stdout);

        sleep(1);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

