#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN	17
#define ECHO_PIN	18
#define CONSUMER	"hc-sr04"
#define MAX_DISTANCE_CM	400.0f
#define MIN_DISTANCE_CM	2.0f

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

/*
 * Wait for edge transitions on `line` for up to `timeout_ns`.
 * Returns 1 on success, -1 on timeout, 0 on signal/interrupt.
 */
static int wait_for_edge(struct gpiod_line *line, int val, long long timeout_ns)
{
    struct timespec ts_start, ts_now;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    while (running) {
        int v = gpiod_line_get_value(line);
        if (v == -1) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (v == val) return 1;

        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long long elapsed =
            (long long)(ts_now.tv_sec - ts_start.tv_sec) * 1000000000LL +
            (ts_now.tv_nsec - ts_start.tv_nsec);
        if (elapsed >= timeout_ns) return 0;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request trigger as output, initial value LOW */
    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        fprintf(stderr, "Request trigger line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        fprintf(stderr, "Request echo line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Ensure trigger starts LOW */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low write failed: %s\n", strerror(errno));
            break;
        }
        usleep(5);

        /* Send 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Trigger high write failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low reset failed: %s\n", strerror(errno));
            break;
        }

        /*
         * Wait for echo rising edge (device may be absent / unresponsive).
         * Give up after ~50 ms so we don't block forever.
         */
        int rc = wait_for_edge(echo, 1, 50000000LL);
        if (rc <= 0) {
            if (!running) break;
            if (rc == 0) {
                fprintf(stderr, "Echo start timeout - sensor absent or not responding.\n");
            } else {
                fprintf(stderr, "Interrupted before echo start.\n");
            }
            break;
        }

        /* Measure echo pulse width (rising -> falling) */
        long long t_rise = 0;
        clock_gettime(CLOCK_MONOTONIC, &t_rise);

        rc = wait_for_edge(echo, 0, 30000000LL); /* max 30 ms echo */
        if (rc <= 0) {
            if (!running) break;
            fprintf(stderr, "Echo end timeout.\n");
            break;
        }

        long long t_fall = 0;
        clock_gettime(CLOCK_MONOTONIC, &t_fall);

        double elapsed_s = (double)(t_fall.tv_sec - t_rise.tv_sec) +
                           (double)(t_fall.tv_nsec - t_rise.tv_nsec) / 1e9;

        float distance_cm = (float)(elapsed_s * 34300.0 / 2.0);

        if (distance_cm > MAX_DISTANCE_CM || distance_cm < MIN_DISTANCE_CM) {
            printf("Out of range: %.2f cm\n", distance_cm);
        } else {
