#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_PINS 4

static const unsigned int pins[NUM_PINS] = {4, 17, 22, 27};
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        keep_running = 0;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    bool lines_requested = false;
    int ret = EXIT_FAILURE;

    // Set up signal handling for clean exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get and request output lines
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "output_control", 0) < 0) {
            fprintf(stderr, "Failed to request output on pin %u\n", pins[i]);
            goto cleanup;
        }
        lines_requested = true;
    }

    // Apply states: HIGH, LOW, HIGH, LOW
    int values[NUM_PINS] = {1, 0, 1, 0};
    for (int i = 0; i < NUM_PINS && keep_running; i++) {
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Failed to write value to pin %u\n", pins[i]);
            goto cleanup;
        }
        printf("Pin %u: %s\n", pins[i], values[i] ? "HIGH" : "LOW");
    }

    if (!keep_running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("States applied successfully.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    // Release lines if requested
    if (lines_requested) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
