/*
 * DHT11 temperature/humidity reader for Raspberry Pi using libgpiod.
 *
 * Wiring:
 *   DHT11 VCC -> 3V3 (pin 1)
 *   DHT11 GND -> GND (pin 6)
 *   DHT11 DATA-> GPIO4 (pin 7), 4k7-10k pull-up to 3V3
 *
 * Build: gcc -O2 -Wall -Wextra -o dht11 dht11.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define BCM_PIN        4
#define MAX_RETRIES    5

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signum)
{
    (void)signum;
    g_stop = 1;
}

/* Wait for pin to reach target level, returning elapsed nanoseconds or -1. */
static long wait_level(struct gpiod_line *line, int target, long timeout_ns)
{
    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    while (!g_stop) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) break;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                       (t_now.tv_nsec - t_start.tv_nsec);
        if (elapsed > timeout_ns) return -1;
    }
    return (g_stop ? -1 : 0);
}

/*
 * Read 40 bits from the DHT11.
 * Returns 0 on success, -1 on any failure.
 */
static int read_dht11(struct gpiod_line *line, float *temp_c, float *hum_pct)
{
    uint8_t data[5] = {0};
    int laststate = 1;
    int counter   = 0;
    int bit_idx   = 0;

    /* --- Start signal: MCU pulls low >=1 ms, then high 20-40 us --- */
    if (gpiod_line_request_output(line, "dht11", 0) < 0) return -1;
    usleep(2000);                       /* >1 ms low */
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);                         /* 20-40 us high */

    /* Release line: switch to input with pull-up so sensor drives data line. */
    if (gpiod_line_request_input_flags(line, "dht11",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) return -1;

    /*
     * Sensor response: ~80 us low + ~80 us high.
     * We time transitions and decode 40-bit Manchester encoding.
     */
    if (wait_level(line, 0, 200) < 0) return -1;   /* wait for low  (~80 us) */
    if (wait_level(line, 1, 200) < 0) return -1;   /* wait for high (~80 us) */
    if (wait_level(line, 0, 200) < 0) return -1;   /* wait for falling edge */

    /* Decode 40 bits: each bit starts with ~50 us low, then variable high. */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        /* Low phase (~50 us). */
        if (wait_level(line, 1, 200) < 0) return -1;
        /* High phase: duration encodes '0' (~26 us) or '1' (~70 us). */
        if (wait_level(line, 0, 200) < 0) return -1;

        /* Measure high-pulse width. */
        struct timespec t_start, t_now;
        clock_gettime(CLOCK_MONOTONIC, &t_start);
        while (!g_stop) {
            if (gpiod_line_get_value(line) != 0) break;
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            long elapsed = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                           (t_now.tv_nsec - t_start.tv_nsec);
            if (elapsed > 1000) return -1;          /* guard against stall */
        }
        if (g_stop) return -1;

        long high_us = (clock_gettime(CLOCK_MONOTONIC, &t_now) == 0 ?
                        (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                        (t_now.tv_nsec - t_start.tv_nsec) / 1000L :
                        0);

        data[bit_idx / 8] <<= 1;
        if (high_us > 50)                 /* >50 us => '1' */
            data[bit_idx / 8] |= 1;
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4])
        return -1;

    uint16_t raw_hum = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_tmp = ((uint16_t)data[2] << 8) | data[3];

    /* DHT11 sends 0x0D0A when humidity/temp is invalid. */
    if (raw_hum == 0x0D0A || raw_tmp == 0x0D0A)
        return -1;

    *hum_pct = (float)raw_hum / 10.0f;
    *temp_c  = (float)(raw_tmp & 0x7FFF) / 10.0f;
    if (raw_tmp & 0x8000) *temp_c = -*temp_c;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", BCM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    float temp_c = 0.0f, hum_pct = 0.0f;
    bool ok = false;

    for (int attempt = 0; attempt < MAX_RETRIES && !g_stop; ++attempt) {
        if (read_dht11(line, &temp_c, &hum_pct) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp_c, hum_pct);
            ok = true;
            break;
        }
        if (errno == EIO) {
            fprintf(stderr, "Sensor read failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, strerror(errno));
        } else {
            fprintf(stderr, "Read error (attempt %d/%d).\n", attempt + 1, MAX_RETRIES);
        }
        usleep(2000000);  /* 2 s between retries */
    }

    if (!ok) {
        fprintf(stderr, "DHT11 not responding after %d attempts.\n", MAX_RETRIES);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

