    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Error getting one or more lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line individually as output, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                OUTPUT_LINE_3, strerror(errno));
        goto cleanup;
    }

    /* Apply values: line1=1, line2=0, line3=1 */
    if (gpiod_line_set_value(line1, 1) < 0) {
        fprintf(stderr, "Error setting value on line %d: %s\n",
                OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        fprintf(stderr, "Error setting value on line %d: %s\n",
                OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_set_value(line3, 1) < 0) {
        fprintf(stderr, "Error setting value on line %d: %s\n",
                OUTPUT_LINE_3, strerror(errno));
        goto cleanup;
    }

    printf("Output states set:\n");
    printf("GPIO %d = HIGH\n", OUTPUT_LINE_1);
    printf("GPIO %d = LOW\n", OUTPUT_LINE_2);
    printf("GPIO %d = HIGH\n", OUTPUT_LINE_3);
    fflush(stdout);

    /* Wait for signals before exiting cleanly */
    while (keep_running) {
        pause();
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   2
#define OUTPUT_LINE_2   3
#define CYCLES          3
#define PERIOD_SEC      5

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("Starting %d-cycle sequence on GPIO %d and GPIO %d...\n",
           CYCLES, OUTPUT_LINE_1, OUTPUT_LINE_2);

    for (int i = 0; i < CYCLES && g_running; ++i) {
        int v1 = (i % 2 == 0) ? 1 : 0;
        int v2 = (i % 2 == 0) ? 0 : 1;

        if (gpiod_line_set_value(line1, v1) < 0) {
            fprintf(stderr, "Failed to set line %d value: %s\n",
                    OUTPUT_LINE_1, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, v2) < 0) {
            fprintf(stderr, "Failed to set line %d value: %s\n",
                    OUTPUT_LINE_2, strerror(errno));
            goto cleanup;
        }

        printf("Cycle %d: GPIO %d=%d, GPIO %d=%d\n",
               i + 1, OUTPUT_LINE_1, v1, OUTPUT_LINE_2, v2);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < PERIOD_SEC && g_running; ++s) {
            sleep(1);
        }
    }

    if (!g_running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("Sequence completed.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip; gpiod_line_release is safe even if not requested */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

