#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_PINS 5
static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 27};

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        keep_running = 0;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    /* Initialize line pointers to NULL so we can clean up in case of early error */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the gpiochip that exposes BCM GPIOs on the Raspberry Pi */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each pin as an output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "blink", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting blink pattern on GPIOs %u, %u, %u, %u, %u...\n",
           pins[0], pins[1], pins[2], pins[3], pins[4]);

    while (keep_running) {
        for (int i = 0; i < NUM_PINS && keep_running; i++) {
            values[i] = !values[i]; /* Toggle */

            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Error setting value on GPIO %u: %s\n",
                        pins[i], strerror(errno));
                goto cleanup;
            }

            printf("GPIO %u set to %d\n", pins[i], values[i]);
        }

        usleep(50000); /* 0.05 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually (safe even if not requested) */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nCleaned up and exiting.\n");
    } else {
        fprintf(stderr, "\nExiting with error.\n");
    }

    return ret;
}

