#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET     2          /* BCM 2 */
#define CONSUMER        "output-bcm2"

static volatile sig_atomic_t g_interrupted = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_interrupted = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output access to the line */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply HIGH to the line */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set value on line %d: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Output HIGH on BCM GPIO %d\n", LINE_OFFSET);

    /* Wait for signals before releasing */
    while (!g_interrupted) {
        pause();
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN_1 2
#define PIN_2 3
#define PIN_3 18

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PIN_1, PIN_2, PIN_3};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    /* Configure each pin as hardware-PWM-capable output and set it low initially */
    for (int i = 0; i < num_pins; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
            goto cleanup_fail;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d, 0) failed\n", pins[i]);
            goto cleanup_fail;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; ++i) {
            int level = (i % 2 == 0) ? 1 : 0;
            if (gpioPWM(pins[i], level) != 0) {
                fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n", pins[i], level);
            }
        }

        printf("GPIO %d=%s | GPIO %d=%s | GPIO %d=%s\n",
               PIN_1, gpioRead(PIN_1) ? "HIGH" : "LOW",
               PIN_2, gpioRead(PIN_2) ? "HIGH" : "LOW",
               PIN_3, gpioRead(PIN_3) ? "HIGH" : "LOW");

        fflush(stdout);

        time_sleep(0.15);
    }

    /* Clean shutdown path */
    for (int i = 0; i < num_pins; ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;

cleanup_fail:
    gpioTerminate();
    return EXIT_FAILURE;
}

