        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip that exposes BCM GPIO lines on the Raspberry Pi */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "blink", 0) < 0) {
            fprintf(stderr, "Error requesting line %u as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting blink pattern on GPIO 2, 3, 4, 5, 6, 7, 8, 9, 17...\n");

    while (keep_running) {
        for (int i = 0; i < NUM_PINS && keep_running; i++) {
            values[i] = !values[i]; /* Toggle */
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Error setting value on line %u: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
        }

        /* Sleep 0.05 seconds in small increments so signals are caught promptly */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 50000000 };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET     18          /* BCM 18 */
#define CONSUMER        "output-ctrl"

static volatile sig_atomic_t g_interrupted = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_interrupted = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output access to the line */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Drive HIGH */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set value HIGH on line %d: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Output ON (BCM %d)\n", LINE_OFFSET);

    /* Hold for 5 seconds or until interrupted */
    unsigned long waited_us = 0;
    while (waited_us < 5000000UL && !g_interrupted) {
        usleep(100000);            /* 100 ms */
        waited_us += 100000;
    }

    /* Clean up: drive LOW then release */
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Warning: failed to reset value on line %d: %s\n",
                LINE_OFFSET, strerror(errno));
    }
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (g_interrupted) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("Output OFF (BCM %d)\n", LINE_OFFSET);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44

/* Register addresses */
#define REG_RESULT   0x00
#define REG_CONFIG   0x01

/* Config: RN=11(continuous), CT=0, M=11(resolution 12-bit),
 * FC=0, OVF=0, CRF=0, FL=0, L=0, POL=0, ME=0, CTN=0, FL=0, L=0 */
#define CONFIG_VALUE 0xC680

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t wbuf[1] = {reg};
    uint8_t rbuf[2];

    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "I2C write (select reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, rbuf, sizeof(rbuf));
    if (n != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd bytes (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

int main(void) {
    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Configure sensor: continuous conversion, 12-bit resolution */
    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Failed to configure OPT3001.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized at 0x%02X. Reading one sample...\n", OPT3001_ADDR);

    uint16_t raw;
    if (!running && errno == EINTR) {
        fprintf(stderr, "\nInterrupted before first read.\n");
        close(fd);
        return EXIT_SUCCESS;
    }

    if (i2c_read_reg16(fd, REG_RESULT, &raw) < 0) {
        fprintf(stderr, "Failed to read result register.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Sign-extend 16-bit two's complement to 32-bit */
    int32_t signed_raw = (int32_t)raw;
    if (signed_raw & 0x8000) {
        signed_raw |= 0xFFFF0000;
    }

    float voltage = (float)signed_raw / 8192.0f;
    printf("Voltage: %.3f V\n", voltage);

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
