    printf("Reported state -> GPIO %d: %d, GPIO %d: %d\n",
           LINE_OFFSET_1, v1, LINE_OFFSET_2, v2);

    rc = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip cleanly */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

