#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <termios.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE   B9600

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_stop = 1;
}

int main(void)
{
    int fd = -1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", SERIAL_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Clear O_NDELAY so reads block until data arrives */
    if (fcntl(fd, F_SETFL, 0) == -1) {
        perror("fcntl F_SETFL");
        close(fd);
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial port initialized on %s at 9600 baud.\n", SERIAL_PORT);

    char buf[256];
    ssize_t n;

    while (!g_stop) {
        n = read(fd, buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = '\0';
            printf("Received: %s\n", buf);
            fflush(stdout);
        } else if (n == 0) {
            break; /* device disconnected */
        } else if (n == -1 && errno == EAGAIN) {
            continue; /* no data available right now */
        } else if (n == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("read");
            break;
        }
    }

    if (close(fd) == -1) {
        perror("close");
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

