#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip4"
#define LINE_OFFSET     2
#define CYCLES          3
#define PERIOD_SEC      60

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Starting %d-cycle sequence on GPIO %d...\n", CYCLES, LINE_OFFSET);

    for (int i = 0; i < CYCLES && g_running; i++) {
        int val = (i % 2 == 0) ? 1 : 0;

        if (gpiod_line_set_value(line, val) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        printf("Cycle %d/%d: GPIO %d = %d\n", i + 1, CYCLES, LINE_OFFSET, val);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < PERIOD_SEC && g_running; s++)
            sleep(1);
    }

    if (!g_running)
        printf("\nInterrupted by signal.\n");

    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

