        printf("Cycle %d: Value LOW\n", i + 1);
        usleep(100000);
    }

    /* Ensure final state is reported */
    if (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val >= 0) {
            printf("Final state: %s\n", val ? "HIGH" : "LOW");
        } else {
            fprintf(stderr, "Failed to read final state: %s\n", strerror(errno));
        }
    }

    /* Release resources cleanly */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

