        fprintf(stderr, "Warning: could not register signal handlers\n");
    }

    int pins[3] = {PIN_17, PIN_18, PIN_27};
    int duty_values[] = {128, 256, 384};

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], duty_values[i]) != 0) {
                fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pins[i], duty_values[i]);
                gpioTerminate();
