#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define NUM_SENSORS 3
static const int g_pins[NUM_SENSORS] = {4, 17, 18};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Read the raw scratchpad contents of a DS18B20.
 * Returns 0 on success, -1 on failure. */
static int read_scratchpad(const char *basepath, unsigned char sp[9])
{
    char path[256];
    snprintf(path, sizeof(path), "%s/scratchpad", basepath);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    size_t n = fread(sp, 1, 9, fp);
    fclose(fp);

    if (n != 9) {
        fprintf(stderr, "Short read from %s (%zu bytes)\n", path, n);
        return -1;
    }
    return 0;
}

/* Convert the scratchpad into a Celsius value.
 * Returns 0 on success, -1 if the CRC / conversion status checks fail. */
static int convert_to_celsius(const unsigned char sp[9], float *celsius_out)
{
    /* Check power-on reset bit — scratchpad should not be all zeros after a valid read. */
    if (sp[0] == 0 && sp[1] == 0 && sp[2] == 0 &&
        sp[3] == 0 && sp[4] == 0 && sp[5] == 0 &&
        sp[6] == 0 && sp[7] == 0 && sp[8] == 0) {
        fprintf(stderr, "Scratchpad appears uninitialized (all zeros).\n");
        return -1;
    }

    /* Check LSB of the configuration register (bit 0 of byte 4).
     * If set, the conversion was in progress but did not finish. */
    if ((sp[4] & 0x01) != 0) {
        fprintf(stderr, "Conversion incomplete (config reg bit 0 set).\n");
        return -1;
    }

    /* Sign-extend the 16-bit temperature result. */
    short temp_raw = (short)((sp[1] << 8) | sp[0]);
    *celsius_out = (float)temp_raw / 16.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    printf("Starting DS18B20 temperature readings. Press Ctrl+C to stop.\n");

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS && g_running; ++i) {
            char basepath[256];
            snprintf(basepath, sizeof(basepath),
                     "/sys/bus/w1/devices/28-00000%d%d%d%d%d%d%d%d",
                     (g_pins[i] >> 3) & 0xF,
                     (g_pins[i] >> 2) & 0xF,
                     (g_pins[i] >> 1) & 0xF,
                     g_pins[i] & 0xF,
                     (g_pins[i] >> 4) & 0xF,
                     (g_pins[i] >> 5) & 0xF,
                     (g_pins[i] >> 6) & 0xF,
                     (g_pins[i] >> 7) & 0xF);

            unsigned char sp[9];
            if (read_scratchpad(basepath, sp) != 0) {
                fprintf(stderr, "Sensor %d (GPIO %d): read failed\n", i + 1, g_pins[i]);
                continue;
            }

            float celsius;
            if (convert_to_celsius(sp, &celsius) != 0) {
                fprintf(stderr, "Sensor %d (GPIO %d): invalid data\n", i + 1, g_pins[i]);
                continue;
            }

            printf("Sensor %d (GPIO %d): %.2f °C\n", i + 1, g_pins[i], celsius);
        }

        if (g_running) {
            sleep(5);
        }
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR             0x40
#define MEASURE_TEMP_HOLD      0xE3
#define MEASURE_RH_HOLD        0xE5
#define CONVERSION_DELAY_US    50000   /* 50 ms worst-case */
#define SAMPLE_INTERVAL_S      60

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Read a 16-bit big-endian word from the HTU21D after issuing a hold master
 * conversion command. Returns 0 on success, -1 on error. */
static int htu21d_read_word(int fd, uint8_t cmd, uint16_t *out)
{
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(cmd 0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }

    usleep(CONVERSION_DELAY_US);

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read() failed: got %zd bytes (%s)\n",
                r, r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Byte 0 = MSB, Byte 1 = LSB, Byte 2 = CRC — discard CRC byte */
    *out = ((uint16_t)(buf[0] << 8)) | buf[1];
    return 0;
}

/* Convert raw ADC value to temperature in degrees Celsius.
 * Per datasheet: T(°C) = -46.85 + 175.72 * RH / 2^16 */
static float convert_temperature(uint16_t raw)
{
    return -46.85f + 175.72f * ((float)raw / 65536.0f);
}

int main(void)
{
    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HTU21D_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint16_t raw_temp = 0;
        if (htu21d_read_word(fd, MEASURE_TEMP_HOLD, &raw_temp) == 0) {
            float temp_c = convert_temperature(raw_temp);
            printf("Temperature: %.2f °C\n", temp_c);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    fprintf(stderr, "\nExiting cleanly...\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
