#define CHIP_NAME "gpiochip0"
#define LINE_1   4
#define LINE_2   18

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, int_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "blink", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "blink", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LINE_2, strerror(errno));
        goto cleanup;
    }

    while (keep_running) {
        int v1 = gpiod_line_set_value(line1, 1);
        int v2 = gpiod_line_set_value(line2, 1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error setting line values: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d=%d, GPIO %d=%d\n", LINE_1, 1, LINE_2, 1);
        fflush(stdout);

        usleep(50000); /* 0.05 s */

        v1 = gpiod_line_set_value(line1, 0);
        v2 = gpiod_line_set_value(line2, 0);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error clearing line values: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d=%d, GPIO %d=%d\n", LINE_1, 0, LINE_2, 0);
        fflush(stdout);

        usleep(50000); /* 0.05 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines; gpiod_line_release is safe even if not requested */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
