#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   2
#define OUTPUT_LINE_2   3
#define POLL_INTERVAL_S 2

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two output lines */
    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("Output pins initialized to LOW.\n");
    fflush(stdout);

    while (keep_running) {
        static int val1 = 0, val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting line %d value: %s\n",
                    OUTPUT_LINE_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting line %d value: %s\n",
                    OUTPUT_LINE_2, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d=%d, GPIO %d=%d\n", OUTPUT_LINE_1, val1,
               OUTPUT_LINE_2, val2);
        fflush(stdout);

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53

// Register addresses
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32

static volatile sig_atomic_t running = 1;

void intHandler(int dummy) {
    (void)dummy;
    running = 0;
}

int main() {
    // Setup signal handler for clean exit
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = intHandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    const char *i2c_dev = "/dev/i2c-1";
    int fd = open(i2c_dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure ADXL345: Standby mode first, then +/-2g full resolution
    uint8_t config_buf[2];

    // Set DATA_FORMAT register (0x31): 0x0B = +/-2g, full resolution, right justified
    config_buf[0] = DATA_FORMAT;
    config_buf[1] = 0x0B;
    if (write(fd, config_buf, 2) != 2) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Enable measurement by setting POWER_CTL register (0x2D) bit D3=1
    config_buf[0] = POWER_CTL;
    config_buf[1] = 0x08; // Measure mode
    if (write(fd, config_buf, 2) != 2) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADXL345 initialized successfully.\n");

    while (running) {
        uint8_t reg = DATAX0;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error selecting data register: %s\n", strerror(errno));
            break;
        }

        uint8_t data[6];
        ssize_t bytes_read = read(fd, data, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "Error reading data: expected 6 bytes, got %zd (%s)\n", bytes_read, strerror(errno));
            break;
        }

        // Combine little-endian pairs into signed 16-bit values
        int16_t x = (int16_t)((data[1] << 8) | data[0]);
        int16_t y = (int16_t)((data[3] << 8) | data[2]);
        int16_t z = (int16_t)((data[5] << 8) | data[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        usleep(100000); // 0.1 seconds
    }

    // Put device back in standby before exiting
    config_buf[0] = POWER_CTL;
    config_buf[1] = 0x00; // Standby mode
    write(fd, config_buf, 2);

    close(fd);
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_OFFSET 27
#define CYCLES 50
#define DELAY_US 100000

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "output-example", 0) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting %d cycles on GPIO %d...\n", CYCLES, LINE_OFFSET);

    for (int i = 0; i < CYCLES && keep_running; i++) {
        int val = i % 2;
        if (gpiod_line_set_value(line, val) < 0) {
            fprintf(stderr, "Failed to set value: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(DELAY_US);
    }

    if (!keep_running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("Completed %d cycles.\n", CYCLES);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_OFFSET 17

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    if (signal(SIGINT, intHandler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output with initial low state
    ret = gpiod_line_request_output(line, "blink", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting blink loop on GPIO %d...\n", LINE_OFFSET);

    while (keep_running) {
        // Toggle state
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }
        int new_value = !current_value;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Error setting line value: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d set to %d\n", LINE_OFFSET, new_value);

        usleep(1000); // 1ms delay
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

