#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define NUM_SENSORS 4
static const unsigned int sensor_pins[NUM_SENSORS] = {17, 22, 23, 24};
static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

/* Read DHT22 via bit-banging on a single line using libgpiod. */
static bool read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};

    /* Start signal: pull low >= 1 ms, then high 20-40 us. */
    if (gpiod_line_request_output(line, "dht22", 0) < 0)
        return false;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0)
        return false;
    usleep(30);

    /* Switch to input; wait for sensor response. */
    if (gpiod_line_request_input_flags(line, "dht22",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0)
        return false;

    /* Sensor pulls low ~80 us, then high ~80 us. */
    struct timespec ts_start, ts_now;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > 200)
            return false;
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > 200)
            return false;
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > 200)
            return false;
    }

    /* Read 40 bits. Each bit starts with low ~50 us, then high varies:
     *   0: ~26-28 us high
     *   1: ~70 us high
     * We measure the high pulse width after each low. */
    for (int i = 0; i < 40; i++) {
        /* Wait for low-to-high transition (end of low preamble). */
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                              (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
            if (elapsed_us > 200)
                return false;
        }
        /* Measure high duration. */
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &ts_now);
            long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                              (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
            if (elapsed_us > 200)
                return false;
        }
        long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L +
                          (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;

        int idx = i / 8;
        int bit = i % 8;
        if (elapsed_us > 40)
            data[idx] |= (1 << bit);
    }

    /* Checksum validation. */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4])
        return false;

    uint16_t raw_hum = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_tmp = ((uint16_t)data[2] << 8) | data[3];

    *hum = (float)raw_hum / 10.0f;
    if (raw_tmp & 0x8000)
        *temp = -(float)(raw_tmp & 0x7FFF) / 10.0f;
    else
        *temp = (float)raw_tmp / 10.0f;

    return true;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("DHT22 monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", localtime(&now));

        for (int i = 0; i < NUM_SENSORS && running; i++) {
            struct gpiod_line *line = gpiod_chip_get_line(chip, sensor_pins[i]);
            if (!line) {
                fprintf(stderr, "[%s] Error: failed to get line %u: %s\n",
                        tbuf, sensor_pins[i], strerror(errno));
                continue;
            }

            float temp, hum;
            if (read_dht22(line, &temp, &hum)) {
                printf("[%s] Sensor %d (GPIO %u): Temp=%.1fC, Hum=%.1f%%\n",
                       tbuf, i + 1, sensor_pins[i], temp, hum);
            } else {
                fprintf(stderr, "[%s] Sensor %d (GPIO %u): READ_FAILED\n",
                        tbuf, i + 1, sensor_pins[i]);
            }
        }

        if (running)
            sleep(2);
    }

    printf("\nExiting...\n");
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN_17 17
#define PIN_22 22
#define PIN_27 27

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device may be absent)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PIN_17, PIN_22, PIN_27};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    /* Set each pin as a hardware-PWM-capable output and verify */
    for (int i = 0; i < num_pins; ++i) {
        unsigned pin = pins[i];
        gpioSetMode(pin, PI_OUTPUT);
        if (gpioGetMode(pin) != PI_OUTPUT) {
            fprintf(stderr, "Error: cannot set GPIO %u as output\n", pin);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /*
     * Drive each pin at a distinct duty cycle.
     * pigpio hardware PWM range is 0-255; we use 0, 128, 255 so the
     * sequence is visually distinct and stays within the valid range.
     */
    while (running) {
        for (int i = 0; i < num_pins && running; ++i) {
            unsigned pin = pins[i];
            int duty = i;          /* 0, 1, 2 -> scaled below */
            if (duty > 2) duty = 2;
            duty *= 86;           /* 0, 86, 173 */

            if (gpioHardwarePWM(pin, 1000, duty) != 0) {
                fprintf(stderr, "Warning: gpioHardwarePWM(%u) failed\n", pin);
            } else {
                printf("GPIO %u: %4d/255\n", pin, duty);
            }
        }
        fflush(stdout);

        /* Sleep 0.5 s in 100 ms slices so signals are caught promptly */
        for (int ms = 0; ms < 500 && running; ms += 100) {
            usleep(100000);
        }
    }

    /* Clean up: turn off PWM and reset pins before terminating */
    for (int i = 0; i < num_pins; ++i) {
        gpioHardwarePWM(pins[i], 1000, 0);
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET_1   17
#define LINE_OFFSET_2   27

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", LINE_OFFSET_1, LINE_OFFSET_2);

    while (keep_running) {
        static int val1 = 0, val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET_2, strerror(errno));
            goto cleanup;
        }

        printf("Line %d: %d | Line %d: %d\n", LINE_OFFSET_1, val1,
               LINE_OFFSET_2, val2);

        fflush(stdout);

        sleep(1);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

