        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Toggle each line independently */
    if (gpiod_line_set_value(line1, 1) < 0) {
        fprintf(stderr, "Failed to set line %d high: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }
    printf("Line %d set HIGH\n", LINE_OFFSET_1);

    if (gpiod_line_set_value(line2, 1) < 0) {
        fprintf(stderr, "Failed to set line %d high: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }
    printf("Line %d set HIGH\n", LINE_OFFSET_2);

    /* Wait briefly before reading back */
    usleep(500000);

    int v1 = gpiod_line_get_value(line1);
    if (v1 < 0) {
        fprintf(stderr, "Failed to read line %d: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    int v2 = gpiod_line_get_value(line2);
    if (v2 < 0) {
        fprintf(stderr, "Failed to read line %d: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    printf("Line %d value: %d\n", LINE_OFFSET_1, v1);
    printf("Line %d value: %d\n", LINE_OFFSET_2, v2);

    rc = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip cleanly even if interrupted */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    if (g_interrupted) {
        fprintf(stderr, "\nInterrupted by signal.\n");
        return EXIT_FAILURE;
    }

    return rc;
}

