#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN      18          /* BCM pin number */
#define PWM_FREQ     1000        /* Hz            */
#define DUTY_CYCLE   500         /* range 0..1000 */
#define STEP_DELAY_S 0.02        /* seconds       */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    int rc;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio daemon/library access --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        fprintf(stderr, "Ensure the pigpio daemon is running with 'sudo pigpiod'.\n");
        return EXIT_FAILURE;
    }

    /*
     * Set up the PWM channel.
     *
     * gpioSetPWMfrequency() returns the actual frequency set.
     * gpioSetPWMrange() sets the duty-cycle resolution (default 1000).
     * gpioPWM() applies the given duty cycle.
     */
    rc = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed (code %d).\n",
                PWM_PIN, rc);
        goto cleanup_fail;
    }

    rc = gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed (code %d).\n",
                PWM_PIN, PWM_FREQ, rc);
        goto cleanup_fail;
    }

    rc = gpioSetPWMrange(PWM_PIN, 1000);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, 1000) failed (code %d).\n",
                PWM_PIN, rc);
        goto cleanup_fail;
    }

    rc = gpioPWM(PWM_PIN, DUTY_CYCLE);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed (code %d).\n",
                PWM_PIN, DUTY_CYCLE, rc);
        goto cleanup_fail;
    }

    printf("PWM started on BCM GPIO %d at %d Hz, duty=%d/1000.\n",
           PWM_PIN, PWM_FREQ, DUTY_CYCLE);
    fflush(stdout);

    /* --- Main loop: report and sleep until interrupted --- */
    while (g_running) {
        printf("Applying PWM on BCM GPIO %d: duty=%d/1000\n",
               PWM_PIN, DUTY_CYCLE);
        fflush(stdout);

        time_sleep(STEP_DELAY_S);
    }

    /* --- Clean shutdown via normal exit path --- */
    gpioPWM(PWM_PIN, 0);          /* silence the output */
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;

cleanup_fail:
    gpioTerminate();
    return EXIT_FAILURE;
}

