#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_I2C_ADDR 0x29

/* Register addresses */
#define TCS34725_ENABLE   0x80
#define TCS34725_ATIME    0x81
#define TCS34725_CDATAL   0x94
#define TCS34725_CDATAH   0x95
#define TCS34725_RDATAL   0x96
#define TCS34725_RDATAH   0x97
#define TCS34725_GDATAL   0x98
#define TCS34725_GDATAH   0x99
#define TCS34725_BDATAL   0x9A
#define TCS34725_BDATAH   0x9B

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    ssize_t n = write(fd, buf, sizeof(buf));
    return (n == (ssize_t)sizeof(buf)) ? 0 : -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    /* Write register pointer */
    if (write(fd, &reg, 1) != 1)
        return -1;
    /* Read one byte back */
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, 0x12, &id) < 0) {
        fprintf(stderr, "Error: cannot read ID register\n");
        return -1;
    }
    if ((id & 0xF0) != 0x40) {
        fprintf(stderr, "Error: unexpected ID 0x%02X (expected 0x40-0x4F)\n", id);
        return -1;
    }

    /* Power ON + RGBC enable */
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: failed to set ENABLE\n");
        return -1;
    }
    usleep(3000);

    /* Integration time ~2.4 ms (ATIME=0xFF) */
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error: failed to set ATIME\n");
        return -1;
    }
    usleep(3000);

    return 0;
}

static int tcs34725_read_crgb(int fd, uint16_t *clear, uint16_t *red,
                               uint16_t *green, uint16_t *blue) {
    uint8_t cl, ch, rl, rh, gl, gh, bl, bh;

    if (i2c_read_reg8(fd, TCS34725_CDATAL, &cl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_CDATAH, &ch) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATAL, &rl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATAH, &rh) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATAL, &gl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATAH, &gh) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATAL, &bl) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATAH, &bh) < 0) return -1;

    *clear = (uint16_t)((cl << 8) | ch);
    *red   = (uint16_t)((rl << 8) | rh);
    *green = (uint16_t)((gl << 8) | gh);
    *blue  = (uint16_t)((bl << 8) | bh);
    return 0;
}

int main(void) {
    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install signal handlers: %s\n",
                strerror(errno));
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Reading TCS34725... Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_crgb(fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            break;
        }
        printf("R=%u G=%u B=%u C=%u\n", red, green, blue, clear);
        fflush(stdout);
        usleep(200000);
    }

    /* Power down sensor before exiting */
    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

