#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", LINE_OFFSET_1, LINE_OFFSET_2);

    while (keep_running) {
        static int val1 = 0;
        static int val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_2, strerror(errno));
            goto cleanup;
        }

        printf("Line %d: %d | Line %d: %d\n", LINE_OFFSET_1, val1,
               LINE_OFFSET_2, val2);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define OLED_ADDR 0x3C

static volatile sig_atomic_t running = 1;

void intHandler(int dummy) {
    (void)dummy;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int oled_command(int fd, uint8_t cmd) {
    // Control byte: Co=0, D/C#=0 -> command stream
    if (i2c_write_byte(fd, 0x00) == -1) return -1;
    return i2c_write_byte(fd, cmd);
}

int oled_data(int fd, uint8_t data) {
    // Control byte: Co=0, D/C#=1 -> data stream
    if (i2c_write_byte(fd, 0x40) == -1) return -1;
    return i2c_write_byte(fd, data);
}

int oled_init(int fd) {
    // Fundamental commands
    if (oled_command(fd, 0xAE) == -1) return -1; // Display off
    if (oled_command(fd, 0xD5) == -1) return -1; // Set display clock divide ratio/oscillator frequency
    if (oled_command(fd, 0x80) == -1) return -1; // Suggested ratio
    if (oled_command(fd, 0xA8) == -1) return -1; // Set multiplex ratio
    if (oled_command(fd, 0x3F) == -1) return -1; // 64 lines
    if (oled_command(fd, 0xD3) == -1) return -1; // Set display offset
    if (oled_command(fd, 0x00) == -1) return -1; // No offset
    if (oled_command(fd, 0x40) == -1) return -1; // Set start line address
    if (oled_command(fd, 0x8D) == -1) return -1; // Charge pump setting
    if (oled_command(fd, 0x14) == -1) return -1; // Enable charge pump during display on
    if (oled_command(fd, 0x20) == -1) return -1; // Memory addressing mode
    if (oled_command(fd, 0x00) == -1) return -1; // Horizontal addressing mode
    if (oled_command(fd, 0xA1) == -1) return -1; // Segment re-map (column 127 mapped to SEG0)
    if (oled_command(fd, 0xC8) == -1) return -1; // COM scan direction (remapped mode)
    if (oled_command(fd, 0xDA) == -1) return -1; // Set COM pins hardware configuration
    if (oled_command(fd, 0x12) == -1) return -1; // Alternative pin configuration
    if (oled_command(fd, 0x81) == -1) return -1; // Set contrast control
    if (oled_command(fd, 0xCF) == -1) return -1; // Contrast value
    if (oled_command(fd, 0xD9) == -1) return -1; // Set pre-charge period
    if (oled_command(fd, 0xF1) == -1) return -1; // Phase 1: 15 DCLK, Phase 2: 1 DCLK
    if (oled_command(fd, 0xDB) == -1) return -1; // Set VCOMH deselect level
    if (oled_command(fd, 0x40) == -1) return -1; // ~0.77 x VCC
    if (oled_command(fd, 0xA4) == -1) return -1; // Entire display on (resume from RAM content)
    if (oled_command(fd, 0xA6) == -1) return -1; // Normal (non-inverted) display
    if (oled_command(fd, 0xAF) == -1) return -1; // Display on
    return 0;
}

int oled_clear(int fd) {
    for (uint8_t page = 0; page < 8; page++) {
        if (oled_command(fd, 0xB0 + page) == -1) return -1; // Set page start address
        if (oled_command(fd, 0x00) == -1) return -1;         // Set lower column start address
        if (oled_command(fd, 0x10) == -1) return -1;         // Set higher column start address

        for (uint8_t col = 0; col < 128; col++) {
            if (oled_data(fd, 0x00) == -1) return -1;
        }
    }
    return 0;
}

int main() {
    signal(SIGINT, intHandler);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OLED_ADDR) < 0) {
        perror("Failed to acquire I2C bus access/talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    if (oled_init(fd) == -1) {
        fprintf(stderr, "OLED initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        char buffer[16];
        snprintf(buffer, sizeof(buffer), "%d", getpid());

        if (oled_clear(fd) == -1) break;

        // Display text at position (0, 0)
        if (oled_command(fd, 0xB0) == -1) break; // Set page start address to 0
        if (oled_command(fd, 0x00) == -1) break; // Set lower column start address
        if (oled_command(fd, 0x10) == -1) break; // Set higher column start address

        for (size_t i = 0; i < strlen(buffer); i++) {
            if (oled_data(fd, buffer[i]) == -1) break;
        }

        usleep(100000); // 0.1 seconds
    }

    // Clean up
    if (oled_clear(fd) == -1) {
        fprintf(stderr, "Warning: Failed to clear OLED on exit.\n");
    }
    close(fd);
    printf("\nExiting cleanly...\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   2
#define OUTPUT_LINE_2   3
#define OUTPUT_LINE_3   5
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to acquire one or more lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as an output, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Request failed for line %d: %s\n", OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Request failed for line %d: %s\n", OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Request failed for line %d: %s\n", OUTPUT_LINE_3, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d, %d, %d initialized as outputs (low). Press Ctrl+C to exit.\n",
           OUTPUT_LINE_1, OUTPUT_LINE_2, OUTPUT_LINE_3);
    fflush(stdout);

    while (g_running) {
        static const int states[4] = {0, 1, 0, 1};
        static int idx = 0;

        if (gpiod_line_set_value(line1, states[idx]) < 0 ||
            gpiod_line_set_value(line2, states[idx + 1]) < 0 ||
            gpiod_line_set_value(line3, states[idx + 2]) < 0) {
            fprintf(stderr, "Failed to set output values: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("State -> L%d H%d L%d\n", states[idx], states[idx + 1], states[idx + 2]);
        fflush(stdout);

        idx = (idx + 3) % 4; /* cycle through [0,1,0,1] */

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly...\n");

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    // Register signal handlers for clean shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 1 kHz for smooth control
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Main loop: cycle through duty cycles from 0% to 100%
    while (running) {
        for (int i = 0; i <= 100 && running; i++) {
            int duty_cycle = i * 255 / 100; // Map 0-100 to 0-255

            gpioPWM(PWM_PIN_1, duty_cycle);
            gpioPWM(PWM_PIN_2, duty_cycle);
            gpioPWM(PWM_PIN_3, duty_cycle);
            gpioPWM(PWM_PIN_4, duty_cycle);

            printf("Duty Cycle: %d%%\n", i);
            fflush(stdout);

            time_sleep(0.01); // 10ms delay for smoother transition
        }
    }

    // Clean up: turn off PWM and terminate library
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define TIMEOUT_US  50000   /* 50 ms timeout for echo */
#define POLL_MS     200

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("request trigger line as output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("request echo line as input");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }
        usleep(2);

        /* Send 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("set trigger high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low after pulse");
            break;
        }

        /* Wait for echo rising edge (timeout) */
        long elapsed_us = 0;
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo line");
                break;
            }
            elapsed_us += 10;
            usleep(10);
        } while (val == 0 && elapsed_us < TIMEOUT_US && running);

        if (val < 0) {
            break;
        }
        if (elapsed_us >= TIMEOUT_US) {
            printf("No echo received within timeout (%ld us)\n", elapsed_us);
            fflush(stdout);
            usleep(POLL_MS * 1000);
            continue;
        }

        /* Measure echo pulse width (falling edge) */
        elapsed_us = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo line during fall");
                break;
            }
            elapsed_us += 10;
            usleep(10);
        } while (val == 1 && elapsed_us < TIMEOUT_US && running);

        if (val < 0) {
            break;
        }
        if (elapsed_us >= TIMEOUT_US) {
            printf("Echo pulse too long (%ld us)\n", elapsed_us);
            fflush(stdout);
            usleep(POLL_MS * 1000);
            continue;
        }

        double distance_cm = (double)elapsed_us / 58.0;
        printf("Distance: %.2f cm\n", distance_cm);
        fflush(stdout);

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN 18

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    /* Set pin as output */
    gpioSetMode(PIN, PI_OUTPUT);

    while (running) {
        /*
         * Drive each of the three bits independently.
         * pigpio's gpioWrite is safe to call repeatedly within a short
         * period; we use it here for clarity.
         */
        gpioWrite(PIN, 1);
        usleep(333);
        gpioWrite(PIN, 0);
        usleep(667);

        gpioWrite(PIN, 0);
        usleep(500);
        gpioWrite(PIN, 1);
        usleep(500);

        gpioWrite(PIN, 1);
        usleep(250);
        gpioWrite(PIN, 0);
        usleep(750);
    }

    /* Ensure line is left low before releasing */
    gpioWrite(PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

