    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "digital_out", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Setting GPIO %d HIGH\n", LINE_OFFSET);
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting value on line %d: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Sleep briefly to let the output settle before reading it back */
    usleep(500000);

    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading value from line %d: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to HIGH (readback=%d)\n", LINE_OFFSET, val);
    fflush(stdout);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 8

static const unsigned int pins[NUM_PINS] = {1, 4, 5, 6, 21, 22, 23, 24};

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as an output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "output-test", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Apply alternating states */
    for (int i = 0; i < NUM_PINS && keep_running; i++)
        values[i] = i % 2;

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Failed to set value on line %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("GPIO States:\n");
    for (int i = 0; i < NUM_PINS; i++)
        printf("GPIO %u: %d\n", pins[i], values[i]);

    fflush(stdout);

    /* Sleep briefly so the output can be observed before exiting */
    sleep(1);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually (libgpiod v1 API) */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"

static volatile sig_atomic_t keep_running = 1;

void int_handler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Camera initialized successfully.\n");

    while (keep_running) {
        FILE *fp = fopen(IMAGE_FILE, "wb");
        if (!fp) {
            fprintf(stderr, "Error opening file %s: %s\n", IMAGE_FILE, strerror(errno));
            break;
        }

        unsigned char buffer[640 * 480 * 3];
        size_t bytes_written = fwrite(buffer, 1, sizeof(buffer), fp);
        fclose(fp);

        if (bytes_written != sizeof(buffer)) {
            fprintf(stderr, "Error writing to file %s: wrote %zu of %zu bytes\n",
                    IMAGE_FILE, bytes_written, sizeof(buffer));
            break;
        }

        printf("Image saved to %s (%zu bytes)\n", IMAGE_FILE, bytes_written);
        usleep(50000);
    }

    close(fd);
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76

/* BME280 Registers */
#define BME280_REG_ID       0xD0
#define BME280_REG_RESET    0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS   0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG   0xF5
#define BME280_REG_DATA     0xF7

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
    uint8_t  dig_H1;
    int16_t  dig_H2;
    uint8_t  dig_H3;
    int16_t  dig_H4;
    int16_t  dig_H5;
    int8_t   dig_H6;
} bme280_calib_data;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, bme280_calib_data *cal) {
    uint8_t buf[26];
    if (i2c_read_reg(fd, 0x88, buf, 26) != 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    cal->dig_H1 = buf[25];

    uint8_t hbuf[7];
    if (i2c_read_reg(fd, 0xA1, hbuf, 7) != 0) return -1;
    cal->dig_H2 = (int16_t)(hbuf[0] | (hbuf[1] << 8));
    cal->dig_H3 = hbuf[2];
    cal->dig_H4 = (int16_t)((hbuf[3] << 4) | (hbuf[4] & 0x0F));
    cal->dig_H5 = (int16_t)((hbuf[5] << 4) | ((hbuf[4] >> 4) & 0x0F));
    cal->dig_H6 = (int8_t)hbuf[6];
    return 0;
}

static int bme280_init(int fd, bme280_calib_data *cal) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60).\n", id);
        return -1;
    }

    if (read_calibration(fd, cal) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }

    /* Humidity x1 */
    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) != 0) return -1;

    /* Config: t_sb=0.5ms(001), filter=off(000), spi3w_en=0 */
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0x00) != 0) return -1;

    /* Ctrl_meas: osrs_t=x1(001), osrs_p=x1(001), mode=normal(11) -> 0b00100111 */
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) != 0) return -1;

    usleep(10000);
    return 0;
}

static int bme280_read_raw(int fd, int32_t *temp, int32_t *press, int32_t *hum) {
    uint8_t d[8];
    if (i2c_read_reg(fd, BME280_REG_DATA, d, 8) != 0) return -1;
    *press = ((int32_t)d[0] << 12) | ((int32_t)d[1] << 4) | (d[2] >> 4);
    *temp  = ((int32_t)d[3] << 12) | ((int32_t)d[4] << 4) | (d[5] >> 4);
    *hum   = ((int32_t)d[6] << 8)  | (d[7]);
    return 0;
}

static void sleep_ms(unsigned ms) {
    while (ms > 0 && running) {
        unsigned chunk = (ms > 100) ? 100 : ms;
        usleep(chunk * 1000U);
        ms -= chunk;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    bme280_calib_data cal;
    if (bme280_init(fd, &cal) != 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BME280 initialized successfully.\n");

    while (running) {
        int32_t raw_t, raw_p, raw_h;
        if (bme280_read_raw(fd, &raw_t, &raw_p, &raw_h) != 0) {
            fprintf(stderr, "Warning: Failed to read sensor data (%s). Retrying...\n", strerror(errno));
            sleep_ms(5000);
            continue;
        }

        double temp = ((double)raw_t / 16384.0) * cal.dig_T1 + 25.0;
        double press = ((double)raw_p / 16384.0) * cal.dig_P1;
        double hum = ((double)raw_h / 16384.0) * cal.dig_H1;

        printf("Temperature: %.2f C, Pressure: %.2f Pa, Humidity: %.2f %%\n", temp, press, hum);
        fflush(stdout);

        sleep_ms(5000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* Register addresses */
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

/*
 * Config word:
 *   OS=1 (start single conversion)
 *   MUX=100 (AIN0 vs GND) | PGA=000 (+/-4.096V) | MODE=1 (single-shot)
 *   DR=100 (128 SPS) | COMP_MODE=0 | COMP_POL=0 | COMP_LAT=0 | COMP_QUE=11
 * => 0xC3E3 = 0b1100001111100011
 */
#define CONFIG_VALUE   0xC3E3

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADS1115 slave address */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Trigger a single-shot conversion.
     * i2c_smbus_write_word_data sends data in little-endian format,
     * which matches the ADS1115 register layout.
     */
    __u16 config_le = (__u16)CONFIG_VALUE;
    if (i2c_smbus_write_word_data(fd, REG_CONFIG, config_le) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Wait for the conversion to complete (~8 ms at 128 SPS).
     * Sleep in small increments so we can respond to signals promptly.
     */
    for (int i = 0; i < 20 && g_running; i++) {
        usleep(4000);
    }
    if (!g_running) {
        goto cleanup;
    }

    /*
     * Read the conversion result.
     * i2c_smbus_read_word_data returns the byte-swapped value received
     * from the device, so we swap it back to host order.
     */
    __u16 raw = (__u16)i2c_smbus_read_word_data(fd, REG_CONVERSION);
    if (raw == 0xFFFF) {
        fprintf(stderr, "Error reading conversion register: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Swap bytes: ADS1115 sends [low_byte, high_byte] */
    uint16_t swapped = ((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF);

    /* Sign-extend from 16 bits to 32 bits */
    int16_t signed_val = (int16_t)swapped;

    printf("ADC Value: %d\n", signed_val);
    fflush(stdout);

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET     4          /* BCM pin 4 */
#define POLL_INTERVAL   60         /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM pin 4 */
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output control of the line */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d configured as output.\n", LINE_OFFSET);

    while (g_running) {
        int value = (rand() % 2) ? 1 : 0;

        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            break;
        }

        printf("Value written to GPIO %d: %d\n", LINE_OFFSET, value);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

/* MPU6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Wake up the MPU6050 by writing 0x00 to PWR_MGMT_1.
     * A NACK here typically means the sensor is not present.
     */
    uint8_t pwr_cmd[2] = { PWR_MGMT_1, 0x00 };
    ssize_t wrcnt = write(fd, pwr_cmd, sizeof(pwr_cmd));
    if (wrcnt != (ssize_t)sizeof(pwr_cmd)) {
        fprintf(stderr, "Failed to wake MPU6050 (write returned %zd): %s\n",
                wrcnt, strerror(errno));
        goto cleanup;
    }

    usleep(100000); /* allow oscillator to stabilize */

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        ssize_t wrcnt = write(fd, &reg, 1);
        if (wrcnt != 1) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                    reg, strerror(errno));
            break;
        }

        uint8_t buf[6];
        ssize_t rdcnt = read(fd, buf, sizeof(buf));
        if (rdcnt != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "Error reading accelerometer data (read %zd bytes): %s\n",
                    rdcnt, strerror(errno));
            break;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n",
               accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(10000); /* 10 ms -> ~100 Hz */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

