#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_OFFSET 23

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "blink", 0);
    if (ret != 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret != 0) {
            fprintf(stderr, "Error setting value high: %s\n", strerror(errno));
            break;
        }
        printf("GPIO %d set HIGH\n", LINE_OFFSET);
        fflush(stdout);

        usleep(50000); /* 0.05 s */

        ret = gpiod_line_set_value(line, 0);
        if (ret != 0) {
            fprintf(stderr, "Error setting value low: %s\n", strerror(errno));
            break;
        }
        printf("GPIO %d set LOW\n", LINE_OFFSET);
        fflush(stdout);

        usleep(50000); /* 0.05 s */
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LCD_ADDR 0x27

// HD44780 commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME   0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

// Entry mode flags
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01

// Display control flags
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Function set flags
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int lcd_write_byte(int fd, unsigned char val, int rs) {
    unsigned char data_u[4];
    unsigned char data_l[4];

    // Upper nibble
    data_u[0] = val & 0xF0; // Upper nibble
    data_u[1] = val & 0xF0; // Upper nibble
    data_u[2] = val & 0xF0; // Upper nibble
    data_u[3] = val & 0xF0; // Upper nibble

    // Lower nibble
    data_l[0] = (val << 4) & 0xF0; // Lower nibble
    data_l[1] = (val << 4) & 0xF0; // Lower nibble
    data_l[2] = (val << 4) & 0xF0; // Lower nibble
    data_l[3] = (val << 4) & 0xF0; // Lower nibble

    // Enable pulse with RS bit
    if (ioctl(fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    // Send upper nibble
    if (write(fd, &data_u[0], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);
    if (write(fd, &data_u[1], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);
    if (write(fd, &data_u[2], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);
    if (write(fd, &data_u[3], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);

    // Send lower nibble
    if (write(fd, &data_l[0], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);
    if (write(fd, &data_l[1], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);
    if (write(fd, &data_l[2], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);
    if (write(fd, &data_l[3], 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(1);

    return 0;
}

int lcd_command(int fd, unsigned char cmd) {
    return lcd_write_byte(fd, cmd, 0);
}

int lcd_data(int fd, unsigned char data) {
    return lcd_write_byte(fd, data, 1);
}

int lcd_init(int fd) {
    usleep(50000); // Wait > 40ms after power-on

    // Initialization sequence for 4-bit interface
    if (lcd_write_byte(fd, 0x30, 0) < 0) return -1; usleep(5000);
    if (lcd_write_byte(fd, 0x30, 0) < 0) return -1; usleep(1000);
    if (lcd_write_byte(fd, 0x30, 0) < 0) return -1; usleep(1000);
    if (lcd_write_byte(fd, 0x20, 0) < 0) return -1; usleep(1000); // Switch to 4-bit mode

    // Now in 4-bit mode, send function set command
    if (lcd_command(fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS) < 0) return -1;
    if (lcd_command(fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF) < 0) return -1;
    if (lcd_command(fd, LCD_CLEARDISPLAY) < 0) return -1;
    usleep(2000);
    if (lcd_command(fd, LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTINCREMENT) < 0) return -1;

    return 0;
}

int lcd_set_cursor(int fd, int row, int col) {
    unsigned char addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else {
        addr = 0x40 + col;
    }
    return lcd_command(fd, LCD_SETDDRAMADDR | addr);
}

int lcd_print_string(int fd, const char *str) {
    while (*str) {
        if (lcd_data(fd, *str++) < 0) return -1;
    }
    return 0;
}

int main() {
    int fd;
    char buffer[64];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (lcd_init(fd) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Starting LCD display loop...\n");

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        snprintf(buffer, sizeof(buffer), "Time: %s", timestamp);

        if (lcd_set_cursor(fd, 0, 0) < 0) break;
        if (lcd_print_string(fd, buffer) < 0) break;

        sleep(10);
    }

    // Clear display before exiting
    lcd_command(fd, LCD_CLEARDISPLAY);
    usleep(2000);

    close(fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

/* MPU6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo) {
    (void)signo;
    g_running = 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Wake up the MPU6050 (clear sleep bit in PWR_MGMT_1) */
    uint8_t pwr_mgmt[2] = {PWR_MGMT_1, 0x00};
    ssize_t wrcnt = write(fd, pwr_mgmt, sizeof(pwr_mgmt));
    if (wrcnt != (ssize_t)sizeof(pwr_mgmt)) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n",
                wrcnt < 0 ? strerror(errno) : "short write");
        goto cleanup;
    }

    usleep(100000); /* allow oscillator to stabilize */

    printf("MPU6050 initialized at 0x%02X.\n", MPU6050_ADDR);

    for (int i = 0; i < 100 && g_running; ++i) {
        uint8_t reg = ACCEL_XOUT_H;
        ssize_t wrcnt = write(fd, &reg, sizeof(reg));
        if (wrcnt != (ssize_t)sizeof(reg)) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                    reg, wrcnt < 0 ? strerror(errno) : "short write");
            goto cleanup;
        }

        uint8_t buf[6];
        ssize_t rdcnt = read(fd, buf, sizeof(buf));
        if (rdcnt != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "Error reading accelerometer data: %s\n",
                    rdcnt < 0 ? strerror(errno) : "short read");
            goto cleanup;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(10000); /* 10 ms between samples (~100 Hz) */
    }

    if (!g_running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("Completed 100 readings.\n");
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   14
#define OUTPUT_LINE_2   15
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", OUTPUT_LINE_1, OUTPUT_LINE_2);

    while (g_running) {
        int val1 = rand() % 2;
        int val2 = rand() % 2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    OUTPUT_LINE_1, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    OUTPUT_LINE_2, strerror(errno));
            goto cleanup;
        }

        printf("Set GPIO %d to %d, GPIO %d to %d.\n", OUTPUT_LINE_1, val1,
               OUTPUT_LINE_2, val2);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include "MQTTClient.h"

#define ADDRESS     "tcp://localhost:1883"
#define CLIENTID    "ExampleClient"
#define TOPIC       "sensors/temperature"
#define PAYLOAD     "25.6"
#define QOS         1
#define TIMEOUT     1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    int rc;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    if ((rc = MQTTClient_create(&client, ADDRESS, CLIENTID,
                                MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect, return code %d\n", rc);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    while (running) {
        MQTTClient_message pubmsg = MQTTClient_message_initializer;
        MQTTClient_deliveryToken token;

        pubmsg.payload = (void *)PAYLOAD;
        pubmsg.payloadlen = (int)strlen(PAYLOAD);
        pubmsg.qos = QOS;
        pubmsg.retained = 0;

        if ((rc = MQTTClient_publishMessage(client, TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message, return code %d\n", rc);
            break;
        }

        printf("Message with delivery token %d published\n", token);

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            usleep(100000); /* 0.1 s */
        }
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_OFFSET 23

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    if (signal(SIGINT, intHandler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output with initial low state
    ret = gpiod_line_request_output(line, "output_example", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting output loop on GPIO %d...\n", LINE_OFFSET);

    while (keep_running) {
        // Toggle state
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", strerror(errno));
            break;
        }
        int new_value = !current_value;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d set to %d\n", LINE_OFFSET, new_value);

        sleep(5);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define SENSOR_PIN  27

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

/* Returns elapsed nanoseconds between two timespecs. */
static long diff_ns(const struct timespec *start, const struct timespec *end)
{
    return (long)(end->tv_sec - start->tv_sec) * 1000000000L +
           (end->tv_nsec - start->tv_nsec);
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / error.
 */
static float measure_distance(struct gpiod_line *trig,
                               struct gpiod_line *echo)
{
    struct timespec t_start, t_now;
    int val;

    /* Ensure trigger starts low. */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trig low failed: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(5);

    /* 10 us pulse. */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "set trig high failed: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trig low (release) failed: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout ~3 ms). */
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "read echo failed: %s\n", strerror(errno));
            return -1.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        if (diff_ns(&t_start, &t_now) > 3000000L) {   /* 3 ms */
            fprintf(stderr, "Timeout waiting for echo rise.\n");
            return -1.0f;
        }
    } while (val == 0);

    /* Record echo rise time. */
    struct timespec echo_rise;
    clock_gettime(CLOCK_MONOTONIC, &echo_rise);

    /* Wait for echo falling edge (timeout ~80 ms). */
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "read echo failed: %s\n", strerror(errno));
            return -1.0f;
        }
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        if (diff_ns(&echo_rise, &t_now) > 80000000L) {   /* 80 ms */
            fprintf(stderr, "Timeout waiting for echo fall.\n");
            return -1.0f;
        }
    } while (val == 1);

    long duration = diff_ns(&echo_rise, &t_now);
    /* speed of sound 343 m/s => 0.0343 cm/us => 34.3 us/cm round trip. */
    return (float)duration / 34.3f / 2.0f;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("request trig as output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("request echo as input");
        goto cleanup;
    }

    printf("HC-SR04 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float dist = measure_distance(trig, echo);
        if (dist < 0.0f) {
            printf("Error: sensor read failed.\n");
        } else if (dist < 2.0f || dist > 400.0f) {
            printf("Out-of-range: %.2f cm\n", dist);
        } else {
            printf("Distance: %.2f cm\n", dist);
        }
        fflush(stdout);
        usleep(100000);   /* 0.1 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_OFFSET 17

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, intHandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpio chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 17 */
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "blink", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO %d...\n", LINE_OFFSET);

    while (keep_running) {
        /* Toggle the line */
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            break;
        }

        /* Print current state */
        printf("GPIO %d: %s\n", LINE_OFFSET,
               gpiod_line_get_value(line) ? "HIGH" : "LOW");

        sleep(1);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

