void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get one or more lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0 ||
        gpiod_line_request_output(line2, "output-ctrl", 0) < 0 ||
        gpiod_line_request_output(line3, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request output direction: %s\n", strerror(errno));
        goto cleanup;
    }

