    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#include "MQTTClient.h"

#define ADDRESS     "tcp://localhost:1883"
#define CLIENTID    "RaspberryPi_Sensor"
#define TOPIC       "sensor/data"
#define PAYLOAD     "{\"temperature\":25.0,\"humidity\":60.0}"
#define QOS         1
#define TIMEOUT     1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    MQTTClient client;
    int rc = MQTTClient_create(&client, ADDRESS, CLIENTID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client: %s\n", MQTTClient_strerror(rc));
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    printf("Connecting to MQTT broker...\n");
    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }
    printf("Connected successfully.\n");

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)PAYLOAD;
    pubmsg.payloadlen = (int)strlen(PAYLOAD);
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    rc = MQTTClient_publishMessage(client, TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    printf("Waiting for delivery completion...\n");
    while (running && MQTTClient_isConnected(client)) {
        sleep(1);
    }

    rc = MQTTClient_disconnect(client, 1000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Warning: disconnect failed: %s\n", MQTTClient_strerror(rc));
    }

    MQTTClient_destroy(&client);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN      18          /* BCM pin 18 */
#define PWM_FREQ     1000        /* Hz            */
#define DUTY_CYCLE   500         /* 0-1000       */
#define POLL_SEC     5           /* seconds       */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent?)\n");
        return EXIT_FAILURE;
    }

    /*
     * Set up the PWM channel.
     * gpioSetPWMfrequency returns the actual frequency used.
     */
    rc = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed (%d)\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    if (rc <= 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed (%d)\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM initialised on BCM %d at %d Hz, duty %d/1000\n",
           PWM_PIN, rc, DUTY_CYCLE);

    while (g_running) {
        rc = gpioPWM(PWM_PIN, DUTY_CYCLE);
        if (rc < 0) {
            fprintf(stderr, "Warning: gpioPWM(%d, %d) returned %d\n",
                    PWM_PIN, DUTY_CYCLE, rc);
        } else {
            printf("BCM %d PWM=%d\n", PWM_PIN, DUTY_CYCLE);
        }
        fflush(stdout);

        sleep(POLL_SEC);
    }

    /* Clean shutdown: turn off PWM first, then terminate. */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_NS  150000000L  /* 150 ms */
#define POLL_MS     200

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("request trigger line as output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("request echo line as input");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }
        usleep(2);

        /* 10 us pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("set trigger high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low after pulse");
            break;
        }

        struct timespec t_start, t_now;
        clock_gettime(CLOCK_MONOTONIC, &t_start);

        long elapsed_ns = 0;
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo line");
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            elapsed_ns = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                         (t_now.tv_nsec - t_start.tv_nsec);
        } while (val == 0 && elapsed_ns < TIMEOUT_NS);

        if (elapsed_ns >= TIMEOUT_NS) {
            printf("No response from sensor (timeout)\n");
            fflush(stdout);
            usleep(POLL_MS * 1000);
            continue;
        }

        if (val < 0)
            break;

        long start_ns = elapsed_ns;

        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo line");
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            elapsed_ns = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                         (t_now.tv_nsec - t_start.tv_nsec);
        } while (val == 1 && elapsed_ns < TIMEOUT_NS);

        if (val < 0)
            break;

        if (elapsed_ns >= TIMEOUT_NS) {
            printf("Echo stuck high (sensor may be out of range)\n");
            fflush(stdout);
            usleep(POLL_MS * 1000);
            continue;
        }

        double duration_s = (double)(elapsed_ns - start_ns) / 1e9;
        double distance_cm = duration_s * 34300.0 / 2.0;

        if (distance_cm > 400.0 || distance_cm < 2.0) {
            printf("Distance out of range: %.2f cm\n", distance_cm);
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
        }
        fflush(stdout);

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    int pins[4] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    while (running) {
        for (int i = 0; i < num_pins; ++i) {
            int level = gpioRead(pins[i]);
            printf("GPIO %d: %s\n", pins[i], level == PI_HIGH ? "HIGH" : "LOW");
        }
        fflush(stdout);

        time_sleep(0.1);
    }

    /* Clean up: set PWM duty cycle to 0 before terminating */
    for (int i = 0; i < num_pins; ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

