#define DEFAULT_QOS 0

static volatile sig_atomic_t g_interrupted = 0;

static void signal_handler(int signum) {
    (void)signum;
    g_interrupted = 1;
}

typedef struct {
    int temperature;
    int humidity;
} SensorData;

static int read_sensor_data(SensorData *data) {
