        fprintf(stderr, "Error: Invalid temperature value: %d\n", data->temperature);
        return -1;
    }
    if (data->humidity < 0 || data->humidity > 100) {
        fprintf(stderr, "Error: Invalid humidity value: %d\n", data->humidity);
        return -1;
