}

int main(int argc, char *argv[]) {
    const char *broker_address = DEFAULT_BROKER_ADDRESS;
    const char *topic = DEFAULT_TOPIC;
    int qos = DEFAULT_QOS;

    int opt;
    while ((opt = getopt(argc, argv, "b:t:q:h")) != -1) {
        switch (opt) {
            case 'b':
                broker_address = optarg;
                break;
            case 't':
                topic = optarg;
                break;
            case 'q':
                qos = atoi(optarg);
                if (qos < 0 || qos > 2) {
                    fprintf(stderr, "Invalid QoS level: %d\n", qos);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-b broker_address] [-t topic] [-q qos]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    srand(time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    printf("Initializing MQTT client...\n");
    if ((rc = MQTTClient_create(&client, broker_address, DEVICE_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    printf("Connecting to MQTT broker at %s...\n", broker_address);
    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker.\n");

    SensorData sensor_data;
    char *json_payload = NULL;

    if (read_sensor_data(&sensor_data) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        goto cleanup;
    }

    if (validate_sensor_data(&sensor_data) != 0) {
        fprintf(stderr, "Sensor data validation failed.\n");
        goto cleanup;
    }

    json_payload = create_json_payload(&sensor_data);
    if (!json_payload) {
        fprintf(stderr, "Failed to create JSON payload.\n");
        goto cleanup;
    }

    printf("Publishing message: %s\n", json_payload);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = json_payload;
    pubmsg.payloadlen = strlen(json_payload);
    pubmsg.qos = qos;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    if ((rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        free(json_payload);
        goto cleanup;
    }

    printf("Waiting for delivery confirmation...\n");
    while (!g_interrupted) {
        sleep(1);
        if (MQTTClient_isConnected(client)) {
            break;
        }
    }

    if (g_interrupted) {
        fprintf(stderr, "Interrupted by signal.\n");
    } else {
        printf("Message published successfully.\n");
    }

cleanup:
    if (json_payload) {
        free(json_payload);
    }
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define CONFIG_REG     0x01
#define CONVERSION_REG 0x00

/* Config: AIN0 single-ended, PGA +/-4.096V, 128 SPS, continuous */
#define CONFIG_VALUE   0xC3F0

#define NUM_READINGS   10
#define SAMPLE_US      100000  /* 100 ms between samples */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int i2c_handle = -1;
    FILE *mqtt_file = NULL;
    char mqtt_cmd[256];
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure ADS1115 for continuous conversion on AIN0 */
    uint8_t config_buf[3] = {CONFIG_REG, (uint8_t)(CONFIG_VALUE >> 8), (uint8_t)(CONFIG_VALUE & 0xFF)};
    rc = i2cWriteDevice(i2c_handle, (char *)config_buf, 3);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register: %d\n", rc);
        goto cleanup;
    }

    /* Allow first conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    mqtt_file = popen("mosquitto_pub -h localhost -t ads1115/reading -r", "w");
    if (!mqtt_file) {
        perror("popen failed");
        goto cleanup;
    }

    for (int i = 0; i < NUM_READINGS && running; ++i) {
        uint8_t reg = CONVERSION_REG;
        rc = i2cWriteDevice(i2c_handle, (char *)&reg, 1);
        if (rc < 0) {
            fprintf(stderr, "Error selecting conversion register: %d\n", rc);
            break;
        }

        uint8_t data[2] = {0};
        rc = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (rc < 0) {
            fprintf(stderr, "Error reading conversion result: %d\n", rc);
            break;
        }

        int16_t raw_value = ((int16_t)data[0] << 8) | data[1];

        /*
         * PGA = +/-4.096 V => LSB = 187.5 uV.
         * Raw 0..32767 -> 0..+4.096 V; Raw 0..-32768 -> 0..-4.096 V.
         */
        float voltage = (float)raw_value / 32768.0f * 4.096f;

        snprintf(mqtt_cmd, sizeof(mqtt_cmd), "%d", (int)voltage);
        if (fprintf(mqtt_file, "%s\n", mqtt_cmd) < 0) {
            perror("fprintf to mosquitto_pub failed");
            break;
        }
        fflush(mqtt_file);

        printf("Reading %d: Voltage = %.4f V\n", i + 1, voltage);

        usleep(SAMPLE_US);
    }

cleanup:
    if (mqtt_file) {
        pclose(mqtt_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip4"
#define OUTPUT_LINE_1   17
#define OUTPUT_LINE_2   18
#define POLL_INTERVAL_S 0.05

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("Output control started on BCM pins %d and %d.\n", OUTPUT_LINE_1, OUTPUT_LINE_2);

    while (g_running) {
        static int val1 = 0, val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    OUTPUT_LINE_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    OUTPUT_LINE_2, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d | GPIO %d: %d\n", OUTPUT_LINE_1, val1,
               OUTPUT_LINE_2, val2);

        fflush(stdout);

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_OFFSET 17

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    if (signal(SIGINT, intHandler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output with initial low state
    ret = gpiod_line_request_output(line, "output_example", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting output loop on GPIO %d...\n", LINE_OFFSET);

    while (keep_running) {
        // Toggle state
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", strerror(errno));
            break;
        }
        int new_value = !current_value;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d set to %d\n", LINE_OFFSET, new_value);

        sleep(5);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

