#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip4"
#define LINE_OFFSET     22          /* BCM 22 */
#define POLL_INTERVAL_US 100000      /* 0.1 s */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handlers so Ctrl-C / SIGTERM clean up properly. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "blink", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int val = rand() % 2;
        if (gpiod_line_set_value(line, val) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d -> %d\n", LINE_OFFSET, val);
        fflush(stdout);

        /*
         * Sleep in small chunks so signals are caught promptly.
         * usleep returns early with EINTR when interrupted by a signal,
         * which we treat as a normal exit path.
         */
        unsigned int remaining = POLL_INTERVAL_US;
        while (remaining > 0 && g_running) {
            unsigned int chunk = (remaining > 50000) ? 50000 : remaining;
            usleep(chunk);
            remaining -= chunk;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = intHandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    const char *port_name = "/dev/ttyS0";
    int fd = open(port_name, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", port_name, strerror(errno));
        return EXIT_FAILURE;
    }

    // Clear O_NDELAY so read() blocks by default
    if (fcntl(fd, F_SETFL, 0) == -1) {
        fprintf(stderr, "Warning: could not clear O_NDELAY: %s\n", strerror(errno));
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag &= ~PARENB;  // No parity
    tty.c_cflag &= ~CSTOPB;  // One stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;      // 8 data bits
    tty.c_cflag &= ~CRTSCTS; // Disable RTS/CTS hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode, no echo, no signals

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow ctrl
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST; // Raw output

    tty.c_cc[VMIN] = 1;   // Block until at least one byte is received
    tty.c_cc[VTIME] = 5;  // 0.5 second timeout per read()

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial communication initialized on %s at 9600 baud.\n", port_name);

    while (keep_running) {
        unsigned char buffer[256];
        ssize_t num_read = read(fd, buffer, sizeof(buffer));

        if (num_read > 0) {
            for (ssize_t i = 0; i < num_read; ++i) {
                putchar(buffer[i]);
            }
            fflush(stdout);
        } else if (num_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            break;
        }
        // EAGAIN/EWOULDBLOCK means no data available; loop continues
    }

    printf("\nExiting gracefully...\n");

    if (close(fd) == -1) {
        fprintf(stderr, "Error closing serial port: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

/* MPU6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * Wake up the MPU6050 by writing 0x00 to PWR_MGMT_1.
     * A NACK here typically means the sensor is not present.
     */
    uint8_t pwr_cmd[2] = {PWR_MGMT_1, 0x00};
    ssize_t wrcnt = write(fd, pwr_cmd, sizeof(pwr_cmd));
    if (wrcnt != (ssize_t)sizeof(pwr_cmd)) {
        fprintf(stderr, "Failed to wake MPU6050 (write returned %zd): %s\n",
                wrcnt, strerror(errno));
        goto cleanup;
    }

    usleep(100000); /* allow oscillator to stabilize */

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        ssize_t wrcnt = write(fd, &reg, 1);
        if (wrcnt != 1) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                    reg, strerror(errno));
            break;
        }

        uint8_t buf[6];
        ssize_t rdcnt = read(fd, buf, sizeof(buf));
        if (rdcnt != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "Error reading accelerometer data (read %zd bytes): %s\n",
                    rdcnt, strerror(errno));
            break;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n",
               accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76

/* BMP280 Registers */
#define BMP280_REG_ID       0xD0
#define BMP280_REG_RESET    0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG   0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify chip ID */
    uint8_t id = 0;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "BMP280 not responding at 0x%02X: %s\n",
                BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != 0x58) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x58)\n", id);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Soft-reset failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(2000);

    /* Config: t_sb=500ms(0b011), filter=off(0b000), spi3w_en=0 -> 0x27 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Ctrl_meas: osrs_t=x1(0b001), osrs_p=x1(0b001), mode=sleep(0b11) -> 0x27 */
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint8_t data[6];
        if (i2c_read_burst(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            break;
        }

        int32_t raw_press = ((int32_t)data[0] << 12) |
                            ((int32_t)data[1] << 4)  |
                            ((int32_t)data[2] >> 4);
        int32_t raw_temp  = ((int32_t)data[3] << 12) |
                            ((int32_t)data[4] << 4)  |
                            ((int32_t)data[5] >> 4);

        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n",
               (double)raw_temp / 100.0,
               (double)raw_press / 100.0);
        fflush(stdout);

        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN      4   /* BCM pin number */
#define PWM_FREQ     1000 /* Hz — common audio / servo frequency */
#define DUTY_CYCLE   500  /* 0–1000000 range; 500 = 50 % */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    /*
     * Set up the PWM channel.
     * gpioPWM uses a duty-cycle value in microseconds per period,
     * where the period is derived from gpioSetPWMfrequency.
     * A higher frequency => shorter period => smaller duty value.
     */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: cannot set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN, DUTY_CYCLE) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM initialised on GPIO %d at %d Hz, duty %d us (%.1f%%)\n",
           PWM_PIN, PWM_FREQ, DUTY_CYCLE,
           (double)DUTY_CYCLE / 10000.0);

    /* Keep running until a signal arrives, then clean up. */
    while (g_running) {
        pause();
    }

    gpioPWM(PWM_PIN, 0);          /* silence the line */
    gpioSetMode(PWM_PIN, PI_INPUT);/* leave pin high-impedance */
    gpioTerminate();

    printf("\nPWM stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
