#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_5   5
#define LINE_6   6
#define LINE_13  13

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line5 = NULL, *line6 = NULL, *line13 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line5 = gpiod_chip_get_line(chip, LINE_5);
    line6 = gpiod_chip_get_line(chip, LINE_6);
    line13 = gpiod_chip_get_line(chip, LINE_13);
    if (!line5 || !line6 || !line13) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_output(line5, "output", 0) < 0 ||
        gpiod_line_request_output(line6, "output", 0) < 0 ||
        gpiod_line_request_output(line13, "output", 0) < 0) {
        perror("Failed to request output direction");
        goto cleanup;
    }

    printf("GPIO %d: %s\n", LINE_5, "LOW");
    printf("GPIO %d: %s\n", LINE_6, "HIGH");
    printf("GPIO %d: %s\n", LINE_13, "LOW");

