    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include "MQTTClient.h"

#define ADDRESS     "tcp://localhost:1883"
#define CLIENTID    "RaspberryPi_Sensor"
#define TOPIC       "sensor/data"
#define PAYLOAD     "{\"temperature\":25.0,\"humidity\":60.0}"
#define QOS         1
#define TIMEOUT     1000

static volatile sig_atomic_t running = 1;

void intHandler(int dummy) {
    (void)dummy;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = intHandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    MQTTClient client;
    int rc;

    if ((rc = MQTTClient_create(&client, ADDRESS, CLIENTID,
                                MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect, return code %d\n", rc);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Publishing message: %s\n", timestamp, PAYLOAD);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = (void *)PAYLOAD;
    pubmsg.payloadlen = (int)strlen(PAYLOAD);
    pubmsg.qos = QOS;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, TOPIC, &pubmsg, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    printf("%s - Message published successfully.\n", timestamp);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 5

static const int pins[NUM_PINS] = {2, 3, 18, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Ensure cleanup even if we receive a signal during setup */
    if (!running) {
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    for (int i = 0; i < NUM_PINS; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: cannot set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /*
     * Drive each pin HIGH initially so the user can verify the line is
     * driven by the Pi before continuing.
     */
    for (int i = 0; i < NUM_PINS; ++i) {
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: cannot write HIGH to GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM outputs ON: ");
    for (int i = 0; i < NUM_PINS; ++i) {
        printf("%d ", pins[i]);
    }
    printf("\n");

    /* Sleep briefly to let the user observe the output state */
    time_sleep(2.0);

    /* Clean up: drive LOW then release the pins */
    for (int i = 0; i < NUM_PINS; ++i) {
        gpioWrite(pins[i], 0);
        gpioSetMode(pins[i], PI_INPUT);
    }

    gpioTerminate();

    printf("PWM outputs OFF\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN_17 17
#define PIN_22 22
#define PIN_27 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers.\n");
    }

    int pins[3] = {PIN_17, PIN_22, PIN_27};
    const char *states[] = {"HIGH", "LOW"};
    int duty_values[3] = {128, 64, 192};

    while (running) {
        for (int i = 0; i < 3; ++i) {
            gpioSetMode(pins[i], PI_OUTPUT);
            gpioPWM(pins[i], duty_values[i]);
            printf("GPIO %d set to %s\n", pins[i], states[duty_values[i] > 127 ? 0 : 1]);
        }
        fflush(stdout);
        time_sleep(0.05);
    }

    for (int i = 0; i < 3; ++i) {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    printf("\npigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    enum v4l2_buf_type type;
    FILE *fp = NULL;
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Open the video device */
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        goto cleanup;
    }

    /* Verify the device supports V4L2 */
    memset(&cap, 0, sizeof(cap));
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    /* Set format: MJPEG at 640x480 */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request buffers */
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Query buffer */
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Map buffer */
    char *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == buffer) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Start streaming */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        goto cleanup;
    }

    /* Capture one frame */
    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", IMAGE_FILE, strerror(errno));
        goto streamoff;
    }

    /* Queue buffer */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto streamoff;
    }

    /* Dequeue buffer */
    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        goto streamoff;
    }

    size_t bytes_to_write = (size_t)(buf.bytesused > 0 ? buf.bytesused : buf.length);
    if (fwrite(buffer, 1, bytes_to_write, fp) != bytes_to_write) {
        fprintf(stderr, "Error writing to %s: %s\n", IMAGE_FILE, strerror(errno));
        goto streamoff;
    }

    printf("Image saved as %s (%zu bytes)\n", IMAGE_FILE, bytes_to_write);

streamoff:
    fclose(fp);
    fp = NULL;

    /* Stop streaming */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
    }

    munmap(buffer, buf.length);
    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return ret;
}

