#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600

static volatile sig_atomic_t running = 1;

static void int_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    /* Clear O_NDELAY so read() blocks by default */
    if (fcntl(fd, F_SETFL, 0) == -1) {
        perror("fcntl F_SETFL");
        close(fd);
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error from tcgetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;   /* No parity */
    tty.c_cflag &= ~CSTOPB;   /* One stop bit */
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;       /* 8 data bits */
    tty.c_cflag &= ~CRTSCTS;  /* Disable RTS/CTS flow control */
    tty.c_cflag |= CREAD | CLOCAL; /* Enable receiver, ignore modem control */

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); /* Non-canonical mode */
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         /* Turn off s/w flow ctrl */
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;                          /* Raw output */

    tty.c_cc[VMIN] = 1;     /* Block until at least one byte is received */
    tty.c_cc[VTIME] = 5;    /* 0.5s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error from tcsetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial communication initialized on %s at 9600 baud.\n", SERIAL_PORT);

    char buffer[256];
    ssize_t num_read;

    while (running && (num_read = read(fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[num_read] = '\0';
        printf("Received: %s\n", buffer);
        fflush(stdout);
    }

    if (!running) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    } else if (num_read == -1) {
        perror("Error reading from serial port");
    }

    if (close(fd) == -1) {
        perror("Error closing serial port");
        return EXIT_FAILURE;
    }

    printf("Serial communication terminated.\n");
    return EXIT_SUCCESS;
}

