#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN      18   /* BCM pin number */
#define PWM_FREQ     1000 /* Hz */
#define DUTY_CYCLE   500  /* range 0..range; 50% of 255 */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /*
     * Set up PWM on BCM 18.
     * gpioPWM uses a duty cycle in the range 0 .. range-1.
     * A frequency of 1 kHz is requested; pigpio selects the best
     * hardware clock divisor internally.
     */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: cannot set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, 256) != 0) {          /* default 256 => 0..255 */
        fprintf(stderr, "Error: cannot set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN, DUTY_CYCLE) != 0) {
        fprintf(stderr, "Error: cannot start PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on BCM GPIO %d at %d Hz, duty %d/%d.\n",
           PWM_PIN, PWM_FREQ, DUTY_CYCLE, 255);

    while (g_running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown: silence PWM first, then release the pin. */
    gpioPWM(PWM_PIN, 0);
    gpioSetMode(PWM_PIN, PI_INPUT);
    gpioTerminate();

    printf("\nPWM stopped and GPIO released.\n");
    return EXIT_SUCCESS;
}

