    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 5

static const int pins[NUM_PINS] = {8, 9, 10, 11, 17};

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    /* Set each pin as a hardware-PWM-capable output with a safe frequency */
    for (int i = 0; i < NUM_PINS; ++i) {
        gpioSetMode(pins[i], PI_OUTPUT);
        if (gpioHardwarePWM(pins[i], 1000, 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /*
     * Apply distinct duty cycles so we can visually confirm each channel is
     * driving its own value.  Values are in microseconds per period (range 0-2M).
     */
    unsigned int vals[NUM_PINS] = {100000, 200000, 300000, 400000, 500000};
    for (int i = 0; i < NUM_PINS && running; ++i) {
        if (gpioHardwarePWM(pins[i], 1000, vals[i]) != 0) {
            fprintf(stderr, "Error: failed to update PWM on GPIO %d\n", pins[i]);
            break;
        }
        printf("GPIO %d -> %u us\n", pins[i], vals[i]);
    }

    /* Brief pause so the final states are visible before cleanup */
    gpioDelay(500000);

    /* Release PWM on each pin and restore input mode for safety */
    for (int i = 0; i < NUM_PINS; ++i) {
        gpioHardwarePWM(pins[i], 0, 0);
        gpioSetMode(pins[i], PI_INPUT);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN_17 17
#define PIN_18 18
#define PIN_27 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as outputs */
    gpioSetMode(PIN_17, PI_OUTPUT);
    gpioSetMode(PIN_18, PI_OUTPUT);
    gpioSetMode(PIN_27, PI_OUTPUT);

    int duty_cycle = 0;
    const int step = 10;
    const double interval_s = 0.5;

    while (running) {
        /* Generate a simple square wave pattern */
        duty_cycle += step;
        if (duty_cycle > 100) {
            duty_cycle = 0;
        }

        /* Apply PWM to each pin with a 0-100 range mapped to 0-255 */
        gpioPWM(PIN_17, (unsigned)duty_cycle);
        gpioPWM(PIN_18, (unsigned)duty_cycle);
        gpioPWM(PIN_27, (unsigned)duty_cycle);

        printf("GPIO %d=%3d | GPIO %d=%3d | GPIO %d=%3d\n",
               PIN_17, duty_cycle,
               PIN_18, duty_cycle,
               PIN_27, duty_cycle);
        fflush(stdout);

        time_sleep(interval_s);
    }

    /* Clean up: turn off PWM and terminate pigpio */
    gpioPWM(PIN_17, 0);
    gpioPWM(PIN_18, 0);
    gpioPWM(PIN_27, 0);
    gpioTerminate();

    printf("\npigpio terminated.\n");
    return EXIT_SUCCESS;
}

/*
 * DHT22 temperature/humidity reader for Raspberry Pi using libgpiod.
 *
 * Wiring:
 *   VCC -> 3V3 (pin 1)
 *   GND -> GND (pin 6)
 *   DATA-> GPIO4 (pin 7), 1k-10k pull-up to 3V3
 *
 * Build: gcc -O2 -Wall -Wextra -o dht22 dht22.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define BCM_PIN        4
#define MAX_RETRIES    5

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signum)
{
    (void)signum;
    g_stop = 1;
}

/* Wait for pin to reach target level, returning elapsed nanoseconds or -1. */
static long wait_level(struct gpiod_line *line, int target, long timeout_ns)
{
    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    while (!g_stop) {
        int val = gpiod_line_get_value(line);
        if (val == -1) return -1;
        if (val == target) break;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                       (t_now.tv_nsec - t_start.tv_nsec);
        if (elapsed > timeout_ns) return -1;
    }
    return (g_stop ? -1 : 0);
}

/* Read one bit from the DHT22 data stream. Returns 0/1, or -1 on error. */
static int read_bit(struct gpiod_line *line)
{
    /* MCU pulls low ~50 us before releasing. */
    if (wait_level(line, 0, 1000) != 0) return -1;
    if (wait_level(line, 1, 1000) != 0) return -1;

    /* High phase: 26-28 us low then 70 us high => '0'; 50 us+ => '1'. */
    if (wait_level(line, 0, 1000) != 0) return -1;

    struct timespec t_start, t_now;
    clock_gettime(CLOCK_REALTIME, &t_start);

    while (!g_stop) {
        if (gpiod_line_get_value(line) == 1) break;
        clock_gettime(CLOCK_REALTIME, &t_now);
        long elapsed_us =
            (t_now.tv_sec - t_start.tv_sec) * 1000000L +
            (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > 100) return -1; /* guard against stuck sensor */
    }

    if (g_stop) return -1;

    clock_gettime(CLOCK_REALTIME, &t_now);
    long high_us =
        (t_now.tv_sec - t_start.tv_sec) * 1000000L +
        (t_now.tv_nsec - t_start.tv_nsec) / 1000L;

    return (high_us > 50) ? 1 : 0;
}

/* Read 40 bits from the DHT22. Returns 0 on success, -1 on error. */
static int read_dht22(struct gpiod_line *line, float *temp_c, float *hum_pct)
{
    uint8_t data[5] = {0};
    int rc = -1;

    /* --- Start signal: MCU pulls low >=1 ms, then releases. --- */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);                 /* >1 ms low */
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);                   /* 20-40 us release */

    /* --- Switch to input with pull-up. --- */
    if (gpiod_line_request_input_flags(line, "dht22",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) return -1;

    /* --- Sensor response: ~80 us low then 80 us high. --- */
    if (wait_level(line, 0, 200) != 0) goto out;
    if (wait_level(line, 1, 200) != 0) goto out;

    /* --- Read 40 data bits. --- */
    for (int i = 0; i < 40 && !g_stop; ++i) {
        int b = read_bit(line);
        if (b < 0) goto out;
        data[i / 8] <<= 1;
        data[i / 8] |= (uint8_t)b;
    }
    if (g_stop || i != 40) goto out;

    /* --- Checksum validation. --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22 checksum mismatch (calc=0x%02X recv=0x%02X)\n",
                checksum, data[4]);
        goto out;
    }

    uint16_t raw_h = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_t = ((uint16_t)data[2] << 8) | data[3];

    *hum_pct = (float)raw_h / 10.0f;
    if (raw_t & 0x8000) {
        *temp_c = -(float)(raw_t & 0x7FFF) / 10.0f;
    } else {
        *temp_c = (float)raw_t / 10.0f;
    }
    rc = 0;

out:
    gpiod_line_release(line);
    return rc;
}

int main(void)
{
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    float temp_c, hum_pct;
    bool ok = false;

    for (int attempt = 0; attempt < MAX_RETRIES && !g_stop; ++attempt) {
        if (read_dht22(line, &temp_c, &hum_pct) == 0) {
            printf("{\"temperature\": %.1f, \"humidity\": %.1f}\n",
                   temp_c, hum_pct);
            fflush(stdout);
            ok = true;
            break;
        }
        if (attempt < MAX_RETRIES - 1) usleep(2000000); /* 2 s between retries */
    }

    if (!ok) {
        fprintf(stderr, "Failed to read DHT22 after %d attempts.\n", MAX_RETRIES);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return ok ? EXIT_SUCCESS : EXIT_FAILURE;
}

