    const char *mqtt_client_id      = DEFAULT_MQTT_CLIENT_ID;
    const char *mqtt_topic          = DEFAULT_MQTT_TOPIC;
    int adc_channel                 = DEFAULT_ADC_CHANNEL;
    int adc_resolution              = DEFAULT_ADC_RESOLUTION;

    /* Parse command-line arguments */
    int opt;
    while ((opt = getopt(argc, argv, "b:c:t:r:h")) != -1) {
        switch (opt) {
            case 'b': mqtt_broker_address = optarg; break;
            case 'c': mqtt_client_id      = optarg; break;
            case 't': mqtt_topic          = optarg; break;
            case 'r': adc_resolution      = atoi(optarg);
                      if (adc_resolution <= 0 || adc_resolution > 65535) {
                          fprintf(stderr, "Invalid ADC resolution %d\n", adc_resolution);
                          return EXIT_FAILURE;
                      }
                      break;
            case 'h':
            default:
                fprintf(stderr,
                        "Usage: %s [-b broker] [-c client_id] [-t topic] [-r resolution]\n",
                        argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Validate channel */
    if (adc_channel < 0 || adc_channel > 7) {
        fprintf(stderr, "ADC channel must be between 0 and 7\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    /* Initialize Paho MQTT library */
    int rc = MQTTClient_init();
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to initialize Paho MQTT library\n");
        return EXIT_FAILURE;
    }

    MQTTClient client;
    rc = MQTTClient_create(&client, mqtt_broker_address, mqtt_client_id,
                           MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession      = 1;

    printf("Connecting to MQTT broker at %s...\n", mqtt_broker_address);
    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }
    printf("Connected successfully.\n");

    /*
     * Read from MCP3008 via /dev/spidev0.0.
     * Uses standard Linux SPI character device interface.
     */
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening /dev/spidev0.0");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    /* Configure SPI mode 0, MSB first, 8 bits per word */
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01               (start bit)
     *   tx[1] = (0x08 | ch) << 4   (single-ended + channel, upper nibble)
     *   tx[2] = 0x00               (don't care, clocks out low byte)
     *
     * Result: rx[1] lower 2 bits + rx[2] form the 10-bit value.
     */
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (uint8_t)((0x08 | (adc_channel & 0x07)) << 4);
    tx_buf[2] = 0x00;

    ssize_t written = write(spi_fd, tx_buf, sizeof(tx_buf));
    if (written != (ssize_t)sizeof(tx_buf)) {
        if (written < 0) perror("SPI write failed");
        else fprintf(stderr, "SPI short write (%zd/3)\n", written);
        close(spi_fd);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    ssize_t readen = read(spi_fd, rx_buf, sizeof(rx_buf));
    if (readen != (ssize_t)sizeof(rx_buf)) {
        if (readen < 0) perror("SPI read failed");
        else fprintf(stderr, "SPI short read (%zd/3)\n", readen);
        close(spi_fd);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    /* Scale to requested resolution */
    double scaled_value = (double)adc_value * (adc_resolution - 1) / 1023.0;

    char payload[32];
    snprintf(payload, sizeof(payload), "%.2f", scaled_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload    = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos        = 1;
    pubmsg.retained   = 0;

    MQTTClient_deliveryToken token;
    rc = MQTTClient_publishMessage(client, mqtt_topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
    } else {
        printf("Published: %s\n", payload);
    }

    /* Clean up */
    close(spi_fd);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    MQTTClient_term();

    return EXIT_SUCCESS;
}

