    for (int i = 0; i < NUM_PINS; ++i)
    {
        gpioSetMode(pins[i], PI_OUTPUT);
        /* Set PWM frequency to 1 kHz (reasonable default for most LEDs/servos) */
        gpioSetPWMfrequency(pins[i], 1000);
        /* Start with 50% duty cycle (range is 0-255) */
        gpioPWM(pins[i], 128);
    }

    printf("PWM outputs started on BCM %d, %d, %d, %d, %d, %d.\n",
           pins[0], pins[1], pins[2], pins[3], pins[4], pins[5]);
    fflush(stdout);

    /* Keep running until a signal arrives */
    while (!terminate)
    {
        gpioDelay(100000); /* 100 ms sleep in microseconds */
    }

    /* Clean up: turn off PWM and reset pins before terminating pigpio */
    for (int i = 0; i < NUM_PINS; ++i)
    {
        gpioPWM(pins[i], 0);   /* stop PWM output */
        gpioSetMode(pins[i], PI_INPUT); /* safe input mode */
    }
    gpioTerminate();

    printf("\nPigpio terminated cleanly.\n");
    return EXIT_SUCCESS;
