#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_OFFSET 17

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "blink", 0);
    if (ret != 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading value from line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            break;
        }

        printf("%d\n", val);
        fflush(stdout);

        usleep(10000); /* 0.01 seconds */
    }

    /* Clean up: set line low and release it */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_10   10
#define LINE_11   11

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line10 = NULL;
    struct gpiod_line *line11 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line10 = gpiod_chip_get_line(chip, LINE_10);
    if (!line10) {
        perror("gpiod_chip_get_line(10)");
        goto cleanup;
    }
    line11 = gpiod_chip_get_line(chip, LINE_11);
    if (!line11) {
        perror("gpiod_chip_get_line(11)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (0) */
    if (gpiod_line_request_output(line10, "output-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(10)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line11, "output-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(11)");
        goto cleanup;
    }

    /* Toggle each line independently: line10 HIGH, line11 LOW */
    if (gpiod_line_set_value(line10, 1) < 0) {
        perror("gpiod_line_set_value(10)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line11, 0) < 0) {
        perror("gpiod_line_set_value(11)");
        goto cleanup;
    }

    printf("GPIO %d set HIGH\n", LINE_10);
    printf("GPIO %d set LOW\n", LINE_11);
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line10) gpiod_line_release(line10);
    if (line11) gpiod_line_release(line11);
    if (chip)   gpiod_chip_close(chip);

    return ret;
}

