#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04-reader"
#define TIMEOUT_NS  200000000L   /* 200 ms timeout per half-cycle */

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* --- signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- open gpiochip0 (the main BCM controller on Pi 3/4) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value LOW */
    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        fprintf(stderr, "Request trigger line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        fprintf(stderr, "Request echo line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ready on BCM pins %d (TRIG) / %d (ECHO). Press Ctrl-C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);

    while (running) {
        struct timespec t_start, t_now, deadline;
        long elapsed_ns;
        int val;

        /* Ensure trigger starts LOW */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low write failed: %s\n", strerror(errno));
            break;
        }
        usleep(5);

        /* 10 us pulse to start measurement */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Trigger high write failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low release failed: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo rising edge (timeout) */
        clock_gettime(CLOCK_MONOTONIC, &t_start);
        deadline.tv_sec  = t_start.tv_sec + 1;
        deadline.tv_nsec = t_start.tv_nsec + TIMEOUT_NS;
        if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }

        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
                goto next_cycle;
            }
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            elapsed_ns = (long)(t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                         (long)(t_now.tv_nsec - t_start.tv_nsec);
        } while (val == 0 && elapsed_ns < TIMEOUT_NS && running);

        if (!running) break;
        if (elapsed_ns >= TIMEOUT_NS) {
            fprintf(stderr, "Timeout waiting for echo rise — sensor absent or unresponsive.\n");
            goto next_cycle;
        }

        /* Measure echo pulse width (falling edge) */
        t_start = t_now;
        deadline.tv_sec  = t_start.tv_sec + 1;
        deadline.tv_nsec = t_start.tv_nsec + TIMEOUT_NS;
        if (deadline.tv_nsec >= 1000000000L) { deadline.tv_sec++; deadline.tv_nsec -= 1000000000L; }

        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
                goto next_cycle;
            }
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            elapsed_ns = (long)(t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                         (long)(t_now.tv_nsec - t_start.tv_nsec);
        } while (val == 1 && elapsed_ns < TIMEOUT_NS && running);

        if (!running) break;
        if (elapsed_ns >= TIMEOUT_NS) {
            fprintf(stderr, "Timeout measuring echo fall — sensor may be stuck.\n");
            goto next_cycle;
        }

        double distance_cm = (double)elapsed_ns / 58.0;  /* speed of sound ~343 m/s => 58 ns/cm round-trip */

        printf("Distance: %.2f cm\n", distance_cm);

next_cycle:
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    int pins[4] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int duty_cycles[] = {500, 1000, 1500, 2000};

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
                fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
                goto cleanup;
            }
            if (gpioPWM(pins[i], duty_cycles[i]) != 0) {
                fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pins[i], duty_cycles[i]);
                goto cleanup;
            }
        }

        printf("PWM Values: %d, %d, %d, %d\n",
               duty_cycles[0], duty_cycles[1], duty_cycles[2], duty_cycles[3]);
        fflush(stdout);

        sleep(1);
    }

cleanup:
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
        gpioTerminate();
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "captured_image.jpg"

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the video device */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        fprintf(stderr, "Ensure the camera is enabled via 'sudo raspi-config' and the ribbon is seated.\n");
        return EXIT_FAILURE;
    }

    /* Verify the device supports V4L2 */
    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set format: MJPEG at 640x480 */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Allocate a buffer for capturing one frame */
    ret = ioctl(fd, VIDIOC_REQBUFS, &(struct v4l2_requestbuffers){ .count = 1, .type = V4L2_BUF_TYPE_VIDEO_CAPTURE, .memory = V4L2_MEMORY_MMAP });
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Queue the buffer so the driver can start streaming */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Start streaming */
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing images from %s... Press Ctrl+C to stop.\n", DEVICE_NAME);

    while (keep_running) {
        /* Dequeue the filled buffer */
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        ret = ioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret == -1) {
            if (errno == EAGAIN) {
                usleep(100000); /* 0.1 s backoff before retrying */
                continue;
            }
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            break;
        }

        FILE *fp = fopen(IMAGE_FILE, "wb");
        if (!fp) {
            fprintf(stderr, "Error opening %s: %s\n", IMAGE_FILE, strerror(errno));
            ioctl(fd, VIDIOC_QBUF, &buf);
            usleep(100000);
            continue;
        }

        size_t written = fwrite(buffer, 1, buf.bytesused, fp);
        fclose(fp);

        if (written != buf.bytesused) {
            fprintf(stderr, "Short write to %s (%zu of %u bytes)\n", IMAGE_FILE, written, buf.bytesused);
        } else {
            printf("Saved %s (%u bytes)\n", IMAGE_FILE, buf.bytesused);
        }

        /* Re-queue the buffer for next frame */
        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            fprintf(stderr, "VIDIOC_QBUF (requeue) failed: %s\n", strerror(errno));
            break;
        }

        usleep(100000); /* 0.1 second delay between captures */
    }

    /* Clean shutdown: stop streaming, unmap buffer, close device */
    enum v4l2_buf_type stream_type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ioctl(fd, VIDIOC_STREAMOFF, &stream_type);
    munmap(buffer, buffer_size);
    close(fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

