#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define PCF8574_ADDR 0x20

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo) {
    (void)signo;
    g_stop = 1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                PCF8574_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Quick presence probe: try a zero-length write */
    if (write(fd, NULL, 0) < 0 && errno != ENXIO) {
        fprintf(stderr, "Warning: I2C write probe failed: %s\n", strerror(errno));
    }

    uint8_t values[] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80};
    size_t nvals = sizeof(values) / sizeof(values[0]);

    printf("Writing %zu values to PCF8574 at 0x%02X...\n", nvals, PCF8574_ADDR);

    for (size_t i = 0; i < nvals; ++i) {
        if (g_stop) break;

        ssize_t w = write(fd, &values[i], 1);
        if (w < 0) {
            fprintf(stderr, "I2C write error at index %zu: %s\n", i, strerror(errno));
            goto cleanup;
        }
        if (w == 0) {
            fprintf(stderr, "I2C write returned 0 bytes at index %zu\n", i);
            goto cleanup;
        }

        printf("Wrote 0x%02X (%d)\n", values[i], values[i]);
        usleep(500000);
    }

cleanup:
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing I2C device: %s\n", strerror(errno));
    }
    return g_stop ? EXIT_SUCCESS : EXIT_SUCCESS;
}

