#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN_18 18
#define PIN_23 23
#define PIN_24 24

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    int pins[3] = {PIN_18, PIN_23, PIN_24};
    unsigned duty[3];
    const char *names[3] = {"GPIO18", "GPIO23", "GPIO24"};

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device may be absent)\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; ++i) {
        gpioSetMode(pins[i], PI_OUTPUT);
        /* Range 0-255; 128 = 50% */
        duty[i] = 128;
        if (gpioPWM(pins[i], duty[i]) != 0) {
            fprintf(stderr, "Warning: gpioPWM(%s) failed\n", names[i]);
        }
    }

    while (running) {
        for (int i = 0; i < 3; ++i) {
            printf("%s=%u ", names[i], duty[i]);
        }
        printf("\n");
        fflush(stdout);

        for (int i = 0; i < 3; ++i) {
            duty[i] = (duty[i] + 64) % 256;
            if (gpioPWM(pins[i], duty[i]) != 0) {
                fprintf(stderr, "Warning: gpioPWM(%s) update failed\n", names[i]);
            }
        }
        usleep(100000);
    }

    /* Clean shutdown: turn off PWM and release pin modes */
    for (int i = 0; i < 3; ++i) {
        gpioPWM(pins[i], 0);
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Graceful shutdown on SIGINT / SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Probe: drive trigger high briefly then low.
     * If the sensor is absent the echo pin will stay low.
     */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(10000); /* 10 ms > 23 us min pulse width */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(50000); /* 50 ms settle */

    /* Read current value of echo to confirm it is actually driven */
    int val = gpiod_line_get_value(echo);
    if (val < 0) {
        fprintf(stderr, "Echo pin read failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (val == 1) {
        fprintf(stderr, "HC-SR04 not detected: echo pin reads HIGH without trigger.\n");
        goto cleanup;
    }

    printf("HC-SR04 sensor detected on BCM GPIO %d (trigger) and %d (echo).\n",
           TRIGGER_PIN, ECHO_PIN);
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET     23          /* BCM pin 23 */
#define POLL_INTERVAL   5           /* seconds */

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler so we can clean up even if stopped */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output control of the line */
    ret = gpiod_line_request_output(line, "digital_out", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int val = rand() % 2;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d -> %d\n", LINE_OFFSET, val);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && keep_running; i++)
            sleep(1);
    }

    /* Clean release of the line and chip on every exit path */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

/* MPU6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU6050 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Wake up the MPU6050 (clear sleep bit in PWR_MGMT_1) */
    uint8_t pwr_cmd[2] = {PWR_MGMT_1, 0x00};
    ssize_t wrc = write(fd, pwr_cmd, sizeof(pwr_cmd));
    if (wrc != (ssize_t)sizeof(pwr_cmd)) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n",
                wrc < 0 ? strerror(errno) : "short write");
        goto cleanup;
    }

    usleep(100000); /* allow oscillator to stabilize */

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        ssize_t wrc = write(fd, &reg, 1);
        if (wrc != 1) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                    reg, wrc < 0 ? strerror(errno) : "short write");
            break;
        }

        uint8_t buf[6];
        ssize_t rdc = read(fd, buf, sizeof(buf));
        if (rdc != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "Error reading accelerometer data: %s\n",
                    rdc < 0 ? strerror(errno) : "short read");
            break;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n",
               accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

