        return EXIT_FAILURE;
    }

    // Get lines
    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs, initially low
    ret = gpiod_line_request_output(line1, "output", 0);
    if (ret < 0) { perror("Request output line 1 failed"); goto cleanup; }
    ret = gpiod_line_request_output(line2, "output", 0);
    if (ret < 0) { perror("Request output line 2 failed"); goto cleanup; }
    ret = gpiod_line_request_output(line3, "output", 0);
    if (ret < 0) { perror("Request output line 3 failed"); goto cleanup; }

    // Apply states: HIGH, LOW, HIGH
    ret = gpiod_line_set_value(line1, 1);
    if (ret < 0) { perror("Set value line 1 failed"); goto cleanup; }
    ret = gpiod_line_set_value(line2, 0);
    if (ret < 0) { perror("Set value line 2 failed"); goto cleanup; }
    ret = gpiod_line_set_value(line3, 1);
    if (ret < 0) { perror("Set value line 3 failed"); goto cleanup; }

    printf("Output States: Line1=HIGH, Line2=LOW, Line3=HIGH\n");

cleanup:
    // Release lines and close chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR             0x44
#define MEASUREMENT_CMD_MSB    0x24
#define MEASUREMENT_CMD_LSB    0x0B
#define MEASUREMENT_DELAY_MS   15
#define POLL_INTERVAL_SEC      5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    g_running = 0;
}

/* Read raw temperature and humidity bytes from the SHT31. */
static int read_sht31_data(int fd, uint8_t *data) {
    /* Send measurement command: high repeatability, clock stretching disabled. */
    uint8_t cmd[2] = { MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB };
    ssize_t wret = write(fd, cmd, sizeof(cmd));
    if (wret != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "Error writing measurement command: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    ssize_t rret = read(fd, data, 6);
    if (rret != 6) {
        fprintf(stderr, "Error reading sensor data: expected 6 bytes, got %zd (%s)\n",
                rret, rret < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* Convert raw bytes to physical values with basic validation. */
static int convert_and_validate(const uint8_t *raw, float *temperature, float *humidity) {
    uint16_t t_raw = ((uint16_t)raw[0] << 8) | raw[1];
    uint16_t h_raw = ((uint16_t)raw[3] << 8) | raw[4];

    /* Checksum validation (polynomial 0x31, initial value 0xFF). */
    uint8_t t_crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        t_crc ^= raw[i];
        for (int b = 0; b < 8; b++) {
            t_crc = (t_crc & 0x80) ? (t_crc << 1) ^ 0x31 : (t_crc << 1);
        }
    }
    if (t_crc != raw[2]) {
        fprintf(stderr, "Temperature checksum mismatch: computed 0x%02X, received 0x%02X\n",
                t_crc, raw[2]);
        return -1;
    }

    uint8_t h_crc = 0xFF;
    for (int i = 3; i < 5; i++) {
        h_crc ^= raw[i];
        for (int b = 0; b < 8; b++) {
            h_crc = (h_crc & 0x80) ? (h_crc << 1) ^ 0x31 : (h_crc << 1);
        }
    }
    if (h_crc != raw[5]) {
        fprintf(stderr, "Humidity checksum mismatch: computed 0x%02X, received 0x%02X\n",
                h_crc, raw[5]);
        return -1;
    }

    /* Physical conversions. */
    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks. */
    if (*temperature < -40.0f || *temperature > 125.0f ||
        *humidity < 0.0f     || *humidity > 100.0f) {
        fprintf(stderr, "Out-of-range reading: T=%.2f C, H=%.2f %%\n", *temperature, *humidity);
        return -1;
    }
    return 0;
}

int main(void) {
    const char *device = "/dev/i2c-1";
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", device, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SHT31_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("SHT31 monitoring started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           device, SHT31_ADDR);

    while (g_running) {
        uint8_t raw[6];
        float temperature, humidity;

        if (read_sht31_data(fd, raw) == 0 &&
            convert_and_validate(raw, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed or invalid data received.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int s = 0; s < POLL_INTERVAL_SEC && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    if (close(fd) < 0) {
        fprintf(stderr, "Warning: error closing I2C device: %s\n", strerror(errno));
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 10

static const unsigned int pins[NUM_PINS] = {5, 6, 12, 16, 19, 20, 23, 24, 25, 26};

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as an output, initial value HIGH */
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "output-test", 1) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        vals[i] = 1;
    }

    printf("Output set to HIGH on GPIOs:");
    for (int i = 0; i < NUM_PINS; i++)
        printf(" %u", pins[i]);
    printf("\n");

    /* Sleep briefly so the user can observe the state before exiting */
    sleep(1);

    /* Toggle to LOW and report */
    for (int i = 0; i < NUM_PINS; i++) {
        vals[i] = 0;
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to write line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Output set to LOW on GPIOs:");
    for (int i = 0; i < NUM_PINS; i++)
        printf(" %u", pins[i]);
    printf("\n");

    ret = EXIT_SUCCESS;

cleanup:
    /* Release any successfully requested lines */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   17
#define OUTPUT_LINE_2   22
#define OUTPUT_LINE_3   27

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get one or more lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as an output, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Request failed for line %d: %s\n", OUTPUT_LINE_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Request failed for line %d: %s\n", OUTPUT_LINE_2, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Request failed for line %d: %s\n", OUTPUT_LINE_3, strerror(errno));
        goto cleanup;
    }

    printf("Output pins initialized successfully.\n");

    while (keep_running) {
        static const int states[] = {0, 1};
        size_t idx = 0;

        for (size_t i = 0; i < sizeof(states) / sizeof(states[0]); ++i) {
            if (!keep_running)
                break;

            if (gpiod_line_set_value(line1, states[idx]) < 0 ||
                gpiod_line_set_value(line2, states[idx]) < 0 ||
                gpiod_line_set_value(line3, states[idx]) < 0) {
                fprintf(stderr, "Error setting value on line %zu: %s\n",
                        i + 1, strerror(errno));
                goto cleanup;
            }

            printf("Line %zu set to %d\n", i + 1, states[idx]);
            fflush(stdout);

            sleep(1);
            idx = !idx;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (line3)
        gpiod_line_release(line3);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PIN_17 17
#define PIN_18 18
#define PIN_22 22
#define PIN_27 27

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PIN_17, PIN_18, PIN_22, PIN_27};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && running; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
            goto cleanup;
        }
        if (gpioPWM(pins[i], 50) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d) failed\n", pins[i]);
            goto cleanup;
        }
    }

    printf("GPIO %d=%d, %d=%d, %d=%d, %d=%d\n",
           PIN_17, gpioGetPWMdutycycle(PIN_17),
           PIN_18, gpioGetPWMdutycycle(PIN_18),
           PIN_22, gpioGetPWMdutycycle(PIN_22),
           PIN_27, gpioGetPWMdutycycle(PIN_27));
    fflush(stdout);

cleanup:
    for (int i = 0; i < num_pins; ++i) {
        gpioPWM(pins[i], 0);
        gpioTerminate();
    }
    return EXIT_SUCCESS;
}

