#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_1   2
#define LINE_2   17

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, int_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, int_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("Output initialized to LOW.\n");
    fflush(stdout);

    while (keep_running) {
        /* Toggle each line */
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading line values: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_set_value(line1, !v1) < 0) {
            fprintf(stderr, "Error setting line %d: %s\n", LINE_1, strerror(errno));
            break;
        }

        if (gpiod_line_set_value(line2, !v2) < 0) {
            fprintf(stderr, "Error setting line %d: %s\n", LINE_2, strerror(errno));
            break;
        }

        printf("Toggled outputs. Line %d: %s, Line %d: %s\n",
               LINE_1, !v1 ? "HIGH" : "LOW",
               LINE_2, !v2 ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep for 60 seconds; wake early on signal */
        for (int i = 0; i < 60 && keep_running; i++) {
            sleep(1);
        }
    }

    /* Ensure lines are left in a known state before releasing */
    if (line1) gpiod_line_set_value(line1, 0);
    if (line2) gpiod_line_set_value(line2, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

