#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_FILE "captured_image.jpg"

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    unsigned char *buffer = NULL;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    size_t buffer_size;

    /* Open the video device */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Verify the device supports V4L2 */
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set format: MJPEG at 640x480 */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Request buffers */
    memset(&reqbuf, 0, sizeof(reqbuf));
    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Query and map the buffer */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Queue the buffer */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Start streaming */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Dequeue the frame */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Stop streaming */
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write the JPEG data to a file */
    fp = fopen(CAPTURE_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CAPTURE_FILE, strerror(errno));
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Error writing to %s: %s\n", CAPTURE_FILE, strerror(errno));
        fclose(fp);
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(fp);
    munmap(buffer, buffer_size);
    close(fd);

    printf("Image saved as %s\n", CAPTURE_FILE);
    return EXIT_SUCCESS;
}

