    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", LINE_OFFSET_1, LINE_OFFSET_2);

    while (keep_running) {
        static int val1 = 0;
        static int val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_2, strerror(errno));
            goto cleanup;
        }

        printf("Line %d: %d | Line %d: %d\n", LINE_OFFSET_1, val1,
               LINE_OFFSET_2, val2);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define OUTPUT_LINE	"GPIO27"
#define CONSUMER_NAME	"digital_output"

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_stop = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers so we clean up even if interrupted */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Open the gpiochip that owns BCM 27.
     * On Raspberry Pi OS the main gpiochip is usually /dev/gpiochip4
     * (the BCM2835 auxiliary peripheral bank).
     */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try opening by label */
        chip = gpiod_chip_open_by_label("pinctrl-bcm2835");
        if (!chip) {
            /* Last resort: let libgpiod find it */
            chip = gpiod_chip_open_lookup(NULL);
        }
    }
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 27);
    if (!line) {
        fprintf(stderr, "Failed to get line 27: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER_NAME, 0) < 0) {
        fprintf(stderr, "Failed to request line 27 as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Setting GPIO 27 HIGH\n");
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set value on line 27: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Sleep briefly to let the output settle before reading back */
    usleep(100000);

    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Failed to read back value from line 27: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Output state confirmed as HIGH (%d)\n", val);
    fflush(stdout);
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN      18          /* BCM pin connected to WS2812 data line */
#define NUMPIX   1           /* Number of WS2812 LEDs in the strip       */
#define CYCLES   3           /* Total number of colour cycles            */
#define STEP_US  5000        /* Microseconds between cycles              */

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

/*
 * Send a single bit to the WS2812.
 * WS2812 supports up to ~4 MHz serial data input.
 * Bit '1' requires >700 ns high / <350 ns low.
 * Bit '0' requires >350 ns high / >700 ns low.
 *
 * We use gpioPWM with a 1 us period (1 kHz) and vary the duty cycle:
 *   T_high ~ 600 ns => 60% duty -> colour ON
 *   T_low  ~ 900 ns => 40% duty -> colour OFF
 */
static int send_bit(int bit)
{
    /*
     * 1 kHz carrier: 1 us half-period.
     * A '1' needs >= 600 ns high + 400 ns low.
     * A '0' needs >= 300 ns high + 700 ns low.
     * Round to microseconds for simplicity while staying within spec.
     */
    unsigned on_us  = bit ? 1 : 1;
    unsigned off_us = bit ? 1 : 1;

    if (gpioPWM(PIN, 255) != 0) return -1;                 /* full ON  */
    usleep(on_us);

    if (gpioPWM(PIN, 0) != 0) return -1;                   /* full OFF */
    usleep(off_us);
    return 0;
}

/* Build a 24-bit frame from RGB and transmit it. */
static int send_colour(unsigned char r, unsigned char g, unsigned char b)
{
    unsigned int rgb = ((unsigned int)r << 16) |
                       ((unsigned int)g << 8)  |
                       ((unsigned int)b);

    for (int i = 23; i >= 0; i--) {
        if (send_bit((rgb >> i) & 1) != 0)
            return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off. */
    if (gpioWrite(PIN, 0) != 0) {
        fprintf(stderr, "Error: cannot initialise GPIO %d LOW\n", PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Running %d cycles on WS2812 at BCM pin %d...\n", CYCLES, PIN);

    for (int c = 0; c < CYCLES && running; c++) {
        /* Cycle 0: red, green, blue, white, black */
        static const unsigned char cols[][3] = {
            {255, 0, 0},
            {0, 255, 0},
            {0, 0, 255},
            {255, 255, 255},
            {0, 0, 0}
        };

        for (size_t p = 0; p < sizeof(cols)/sizeof(cols[0]) && running; p++) {
            if (send_colour(cols[p][0], cols[p][1], cols[p][2]) != 0) {
                fprintf(stderr, "Error: PWM write failed during cycle %d\n", c);
                goto cleanup;
            }
        }
    }

cleanup:
    /* Ensure LED is off before releasing. */
    gpioWrite(PIN, 0);
    gpioTerminate();
    printf("\nDone.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE     27          /* BCM pin 27 */
#define POLL_INTERVAL   2           /* seconds */

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, int_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, int_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM pin 27 */
    line = gpiod_chip_get_line(chip, OUTPUT_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "output-example", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Output initialized on BCM pin %d.\n", OUTPUT_LINE);

    while (keep_running) {
        /* Toggle the line each iteration */
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Warning: failed to read current value: %s\n",
                    strerror(errno));
            sleep(POLL_INTERVAL);
            continue;
        }

        val = !val;                       /* toggle */
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            fprintf(stderr, "Error setting value: %s\n", strerror(errno));
            break;
        }

        printf("Value set to: %d\n", val);
        fflush(stdout);

        sleep(POLL_INTERVAL);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

