#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>

#define W1_MASTER_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_PREFIX "w1_slave"
#define MAX_DEVICES 16
#define READ_INTERVAL_SEC 5
#define NUM_READINGS 3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int find_ds18b20(char path[], size_t path_len) {
    DIR *d = opendir(W1_MASTER_DIR);
    if (!d) {
        fprintf(stderr, "Error: cannot open %s: %s\n", W1_MASTER_DIR, strerror(errno));
        return -1;
    }

    struct dirent *entry;
    int found = 0;
    while ((entry = readdir(d)) != NULL && !found) {
        if (strncmp(entry->d_name, W1_SLAVE_PREFIX, strlen(W1_SLAVE_PREFIX)) == 0) {
            snprintf(path, path_len, "%s/%s", W1_MASTER_DIR, entry->d_name);
            found = 1;
        }
    }

    closedir(d);

    if (!found) {
        fprintf(stderr, "Error: no DS18B20 sensor found under %s\n", W1_MASTER_DIR);
        return -1;
    }
    return 0;
}

static float read_temperature(const char *path) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -999.0f;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -999.0f;
    }

    /* Check for CRC pass/fail marker */
    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "Warning: CRC check failed for %s\n", path);
        fclose(fp);
        return -999.0f;
    }

    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading second line of %s\n", path);
        fclose(fp);
        return -999.0f;
    }

    fclose(fp);

    char *temp_str = strstr(line, "t=");
    if (!temp_str) {
        fprintf(stderr, "Error: temperature data not found in %s\n", path);
        return -999.0f;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    if (temp_raw == 0 && errno == EINVAL) {
        fprintf(stderr, "Error parsing temperature value\n");
        return -999.0f;
    }

    return (float)temp_raw / 1000.0f;
}

int main(void) {
    char w1_path[512];

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    if (find_ds18b20(w1_path, sizeof(w1_path)) != 0) {
        return EXIT_FAILURE;
    }

    printf("Found DS18B20 at %s\n", w1_path);

    for (int i = 0; i < NUM_READINGS && g_running; ++i) {
        float temp = read_temperature(w1_path);
        if (temp > -998.0f) {
            printf("Temperature: %.2f °C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        if (i < NUM_READINGS - 1) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

