#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define SETTLE_PIN  24

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *sett = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    sett = gpiod_chip_get_line(chip, SETTLE_PIN);
    if (!trig || !echo || !sett) {
        fprintf(stderr, "Failed to acquire one or more GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04-echo") < 0 ||
        gpiod_line_request_output(sett, "hcsr04-sett", 0) < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    /*
     * Settle: drive SETTLE high briefly so the sensor powers up.
     * A real application might wait ~1 ms after power-up before ranging.
     */
    if (gpiod_line_set_value(sett, 1) < 0) {
        perror("set SETTLE high");
        goto cleanup;
    }
    usleep(5000); /* 5 ms settle time */
    if (gpiod_line_set_value(sett, 0) < 0) {
        perror("clear SETTLE");
        goto cleanup;
    }

    while (running) {
        /* Issue 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("trigger high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("trigger low");
            break;
        }

        /* Wait for echo rising edge (timeout 500 us) */
        int val;
        long waited_us = 0;
        const long step = 10;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                goto cleanup;
            }
            if (waited_us >= 500000L) { /* 500 ms timeout */
                printf("HC-SR04: no response from sensor\n");
                fflush(stdout);
                break;
            }
            usleep(step);
            waited_us += step;
        } while (val == 0);

        if (val != 1)
            continue;

        /* Measure echo pulse width (timeout 30 ms max) */
        long elapsed_us = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                goto cleanup;
            }
            if (val == 0) {
                printf("HC-SR04: echo pulse ended unexpectedly\n");
                fflush(stdout);
                break;
            }
            usleep(step);
            elapsed_us += step;
        } while (elapsed_us < 30000L && running);

        double distance_cm = (double)elapsed_us / 58.0;

        if (distance_cm > 400.0 || distance_cm < 2.0) {
            printf("HC-SR04: out-of-range reading (%.2f cm)\n", distance_cm);
        } else {
            printf("HC-SR04: distance = %.2f cm\n", distance_cm);
        }
        fflush(stdout);

        usleep(100000); /* 0.1 s between readings */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)  gpiod_line_release(trig);
    if (echo)  gpiod_line_release(echo);
    if (sett)  gpiod_line_release(sett);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

