#define CHIP_NAME "gpiochip4"
#define LINE_OFFSET 17
#define CYCLES 10

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "output_example", 0) < 0) {
        fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting %d cycles of toggling GPIO %d...\n", CYCLES, LINE_OFFSET);

    for (int i = 0; i < CYCLES && keep_running; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading value: %s\n", strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line, !val) < 0) {
            fprintf(stderr, "Error setting value: %s\n", strerror(errno));
            break;
        }
        printf("Cycle %d: State set to %d\n", i + 1, !val);
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Exiting.\n");
    return ret;
}

