#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_1_PWM_PIN 4
#define MOTOR_2_PWM_PIN 17
#define MOTOR_3_PWM_PIN 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0)
    {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    int pins[] = {MOTOR_1_PWM_PIN, MOTOR_2_PWM_PIN, MOTOR_3_PWM_PIN};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    while (running)
    {
        for (int i = 0; i < num_pins && running; ++i)
        {
            int pwm_value = gpioGetPWMdutycycle(pins[i]);
            if (pwm_value >= 0)
            {
                printf("Motor %d PWM Value: %d\n", i + 1, pwm_value);
            }
            else
            {
                fprintf(stderr, "Error: Failed to read PWM value for motor %d\n", i + 1);
            }
        }
        fflush(stdout);

        if (running)
        {
            time_sleep(0.1);
        }
    }

    /* Release PWM resources before terminating */
    for (int i = 0; i < num_pins; ++i)
    {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

