/*
 * DHT22 reader for Raspberry Pi using libgpiod.
 *
 * Wiring:
 *   VCC -> 3V3 (pin 1)
 *   GND -> GND (pin 6)
 *   DATA-> GPIO4 (pin 7), 1k-10k pull-up to 3V3
 *
 * Build: gcc -O2 -Wall -Wextra -o dht22 dht22.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define BCM_PIN        4
#define MAX_RETRIES    3

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signum)
{
    (void)signum;
    g_stop = 1;
}

/* Wait for pin to reach target level, returning elapsed nanoseconds or -1. */
static long wait_level(struct gpiod_line *line, int target, long timeout_ns)
{
    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    while (!g_stop) {
        int val = gpiod_line_get_value(line);
        if (val == -1) return -1;
        if (val == target) break;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                       (t_now.tv_nsec - t_start.tv_nsec);
        if (elapsed > timeout_ns) return -1;
    }
    return (g_stop ? -1 : 0);
}

/* Read one bit from the DHT22 data stream. Returns 0/1, or -1 on error. */
static int read_bit(struct gpiod_line *line)
{
    /* MCU pulls low ~50 us before releasing. */
    if (wait_level(line, 0, 1000) != 0) return -1;
    if (wait_level(line, 1, 1000) != 0) return -1;

    /* High phase: 26-28 us low then 70 us high => '0'; 50 us+ => '1'. */
    if (wait_level(line, 0, 1000) != 0) return -1;

    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    while (!g_stop) {
        if (gpiod_line_get_value(line) == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed = (t_now.tv_sec - t_start.tv_sec) * 1000000000L +
                       (t_now.tv_nsec - t_start.tv_nsec);
        if (elapsed > 1000) return -1; /* guard against stuck low */
    }

    if (g_stop) return -1;

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    long high_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                   (t_now.tv_nsec - t_start.tv_nsec) / 1000L;

    return (high_us > 50) ? 1 : 0;
}

/* Read 40 bits from the DHT22. Returns 0 on success, -1 on error. */
static int read_dht22(struct gpiod_line *line, float *temp_c, float *hum_pct)
{
    uint8_t data[5] = {0};
    int rc = -1;

    /* --- Start signal: MCU pulls low >=1 ms, then releases. --- */
    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(2000);                 /* stay low >=1 ms */

    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);                  /* release line briefly */

    /* --- Switch to input with pull-up. --- */
    if (gpiod_line_request_input_flags(line, "dht22",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) return -1;

    /* --- Sensor response: ~80 us low then 80 us high. --- */
    if (wait_level(line, 0, 200) != 0) goto out;
    if (wait_level(line, 1, 200) != 0) goto out;

    /* --- Read 40 data bits. --- */
    for (int i = 0; i < 40; i++) {
        int b = read_bit(line);
        if (b < 0) goto out;
        data[i / 8] = (uint8_t)((data[i / 8] << 1) | b);
    }

    /* --- Checksum validation. --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum mismatch: calc=0x%02X recv=0x%02X\n",
                checksum, data[4]);
        goto out;
    }

    uint16_t raw_h = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_t = (uint16_t)((data[2] << 8) | data[3]);

    *hum_pct = (float)raw_h / 10.0f;

    /* Handle negative temperatures (MSB of temp word). */
    if (raw_t & 0x8000) {
        *temp_c = -(float)(raw_t & 0x7FFF) / 10.0f;
    } else {
        *temp_c = (float)raw_t / 10.0f;
    }

    /* Sanity range checks. */
    if (*temp_c < -40.0f || *temp_c > 80.0f ||
        *hum_pct < 0.0f   || *hum_pct > 100.0f) {
        fprintf(stderr, "Out-of-range reading: T=%.1f H=%.1f\n", *temp_c, *hum_pct);
        goto out;
    }

    rc = 0;

out:
    return rc;
}

int main(void)
{
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *chipname = "gpiochip4";
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        chip = gpiod_chip_open_by_label(chipname);
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(4);
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("DHT22 reader on %s line %d. Press Ctrl+C to stop.\n",
           chipname, BCM_PIN);

    int ok_count = 0;
    for (int cycle = 0; cycle < MAX_RETRIES && !g_stop; cycle++) {
        float temp_c, hum_pct;
        if (read_dht22(line, &temp_c, &hum_pct) == 0) {
            printf("[cycle %d/%d] Temperature: %.1f C, Humidity: %.1f %%\n",
                   cycle + 1, MAX_RETRIES, temp_c, hum_pct);
            ok_count++;
        } else {
            fprintf(stderr, "[cycle %d/%d] Failed to read sensor.\n",
                    cycle + 1, MAX_RETRIES);
        }
        if (cycle < MAX_RETRIES - 1 && !g_stop) sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nReadings received: %d/%d\n", ok_count, MAX_RETRIES);
    return (ok_count > 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

