#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   17
#define OUTPUT_LINE_2   22
#define OUTPUT_LINE_3   23
#define OUTPUT_LINE_4   24

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4];
    unsigned int offsets[4] = {OUTPUT_LINE_1, OUTPUT_LINE_2,
                               OUTPUT_LINE_3, OUTPUT_LINE_4};
    int values[4] = {0, 1, 0, 1};
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %u: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as an output with initial value */
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "output-demo",
                                      values[i]) < 0) {
            fprintf(stderr, "Error requesting line %u as output: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Output pins initialized:\n");
    for (int i = 0; i < 4; i++)
        printf("GPIO %u = %d\n", offsets[i], values[i]);
    fflush(stdout);

    while (keep_running) {
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Error setting line %u: %s\n",
                        offsets[i], strerror(errno));
                goto cleanup;
            }
        }

        printf("Values set:");
        for (int i = 0; i < 4; i++)
            printf(" GPIO%u=%d", offsets[i], values[i]);
        printf("\n");
        fflush(stdout);

        /* Toggle values */
        for (int i = 0; i < 4; i++)
            values[i] = !values[i];

        sleep(10);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually so we can handle partial failures */
    for (int i = 0; i < 4; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   4
#define OUTPUT_LINE_2   17
#define OUTPUT_LINE_3   18
#define CYCLES          5
#define DELAY_SEC       0
#define DELAY_NSEC      50000000L

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);
    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get one or more lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0 ||
        gpiod_line_request_output(line2, "output-ctrl", 0) < 0 ||
        gpiod_line_request_output(line3, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request lines as outputs: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting %d cycles of 0.05 s each...\n", CYCLES);

    for (int i = 0; i < CYCLES && keep_running; i++) {
        int v1 = i % 2;
        int v2 = (i + 1) % 2;
        int v3 = (i + 2) % 2;

        if (gpiod_line_set_value(line1, v1) < 0 ||
            gpiod_line_set_value(line2, v2) < 0 ||
            gpiod_line_set_value(line3, v3) < 0) {
            fprintf(stderr, "Failed to set line values: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("Cycle %d: GPIO%d=%d, GPIO%d=%d, GPIO%d=%d\n",
               i, OUTPUT_LINE_1, v1, OUTPUT_LINE_2, v2, OUTPUT_LINE_3, v3);

        struct timespec ts = { .tv_sec = DELAY_SEC,
                               .tv_nsec = DELAY_NSEC };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && keep_running) {
            /* Retry remaining time after interruption */
        }
    }

    if (!keep_running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("All cycles completed.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually so we can handle partial failure */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PIN_1 17
#define PIN_2 27

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    int p1_state = gpioSetMode(PIN_1, PI_OUTPUT);
    int p2_state = gpioSetMode(PIN_2, PI_OUTPUT);

    if (p1_state != 0 || p2_state != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode (p1=%d, p2=%d)\n",
                p1_state, p2_state);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Apply PWM duty cycles; range is 0..255 by default */
    gpioPWM(PIN_1, 128);
    gpioPWM(PIN_2, 64);

    printf("GPIO %d PWM=128 | GPIO %d PWM=64\n", PIN_1, PIN_2);
    fflush(stdout);

    /* Sleep briefly so the values take effect before we exit */
    time_sleep(0.5);

    /* Clean up hardware resources */
    gpioPWM(PIN_1, 0);
    gpioPWM(PIN_2, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

