                goto cleanup;
            }
        }

        printf("[%d] Pins: %d %d %d %d %d %d %d\n",
               cycle,
               vals[0], vals[1], vals[2], vals[3],
               vals[4], vals[5], vals[6]);

        fflush(stdout);

        /*
         * Sleep 0.5 s in 100 ms slices so we can exit promptly on signal.
         * nanosleep returns EINTR when interrupted by a signal; loop until
         * the requested time elapses or keep_running becomes false.
         */
        struct timespec req = { .tv_sec = 0, .tv_nsec = 500 * 1000 * 1000 };
        while (nanosleep(&req, &req) == -1 && errno == EINTR && keep_running)
            ;
    }

    if (!keep_running)
        printf("\nInterrupted by signal.\n");

    ret = EXIT_SUCCESS;

cleanup:
    /* Release any successfully acquired lines */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

