#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS      4
static const int pins[NUM_PINS] = {4, 17, 18, 27};

/* Cycle waveforms: 0=off, 128=50%, 255=max.
 * Each entry is duty-cycle value; we toggle between 0 and 255. */
static const unsigned char cycle_waveform[] = {
    0, 255, 0, 255, 0, 255, 0, 255,
    0, 255, 0, 255, 0, 255, 0, 255,
    0, 255, 0, 255, 0, 255, 0, 255,
    0, 255, 0, 255, 0, 255, 0, 255,
    0, 255, 0, 255, 0, 255, 0, 255
};
#define CYCLE_LEN (sizeof(cycle_waveform) / sizeof(cycle_waveform[0]))

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Set each pin as output and initialise to LOW */
    for (int i = 0; i < NUM_PINS; ++i) {
        gpioSetMode(pins[i], PI_OUTPUT);
        gpioPWM(pins[i], 0);
    }

    printf("Starting %d-second PWM cycles on BCM pins %d,%d,%d,%d...\n",
           60, pins[0], pins[1], pins[2], pins[3]);
    fflush(stdout);

    while (running && CYCLE_LEN > 0) {
        for (int c = 0; c < CYCLE_LEN && running; ++c) {
            for (int p = 0; p < NUM_PINS; ++p) {
                gpioPWM(pins[p], cycle_waveform[c]);
            }
            time_sleep(0.1); /* 100 ms per step */
        }
    }

    /* Clean up: turn off all outputs and terminate pigpio */
    for (int i = 0; i < NUM_PINS; ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

