/*
 * DHT22 reader for Raspberry Pi using libgpiod.
 *
 * Reads temperature and humidity from a DHT22 sensor on two different
 * BCM pins (4 and 17) over three 60-second cycles, then exits.
 *
 * Build: gcc -O2 -Wall -Wextra -o dht22_reader dht22_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#include <gpiod.h>

#define NUM_CYCLES   3
#define SAMPLE_INTERVAL_S 60

/* ---- Configuration ---- */
static const char *chip_path = "/dev/gpiochip0";
static const unsigned int pin_4    = 4;
static const unsigned int pin_17   = 17;

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip        = NULL;
static struct gpiod_line  *g_line_4      = NULL;
static struct gpiod_line  *g_line_17     = NULL;

static void sighandler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_line_4) {
        gpiod_line_release(g_line_4);
        g_line_4 = NULL;
    }
    if (g_line_17) {
        gpiod_line_release(g_line_17);
        g_line_17 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/*
 * Read DHT22 data from a single line.
 * Returns true on success, false on failure.
 */
static bool read_dht22(struct gpiod_line *line, float *temp_c, float *hum_pct)
{
    uint8_t data[5] = {0};
    int bit_count = 0;

    /* --- Start signal: pull low >=1 ms, then high ~30 us --- */
    if (gpiod_line_request_output(line, "dht22-start", 0) < 0) return false;
    usleep(2000);                       /* >1 ms low */
    if (gpiod_line_set_value(line, 1) < 0) return false;
    usleep(30);                         /* 30 us high */

    /* Release so the sensor drives the line */
    if (gpiod_line_request_input(line, "dht22-read") < 0) return false;

    /*
     * Wait for sensor response: ~80 us low, ~80 us high.
     * Poll with short delays until we see the expected pattern,
     * or timeout (~100 ms).
     */
    int val;
    int waited_us = 0;
    while ((val = gpiod_line_get_value(line)) == 0 && waited_us < 200) {
        usleep(1);
        waited_us++;
    }
    if (val != 1) return false;          /* no response */

    waited_us = 0;
    while ((val = gpiod_line_get_value(line)) == 1 && waited_us < 200) {
        usleep(1);
        waited_us++;
    }
    if (val != 0) return false;

    /* --- Read 40 bits --- */
    for (int i = 0; i < 40; i++) {
        /* Low phase (~50 us) */
        waited_us = 0;
        while ((val = gpiod_line_get_value(line)) == 0 && waited_us < 200) {
            usleep(1);
            waited_us++;
        }
        if (val != 1) return false;

        /* High phase: duration determines bit value */
        waited_us = 0;
        while ((val = gpiod_line_get_value(line)) == 1 && waited_us < 200) {
            usleep(1);
            waited_us++;
        }

        if (waited_us > 50) {
            data[i / 8] |= (uint8_t)(1 << (7 - (i % 8)));
        } else {
            data[i / 8] &= (uint8_t)~(1 << (7 - (i % 8)));
        }
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) return false;

    uint16_t raw_hum = (uint16_t)(((uint16_t)data[0] << 8) | data[1]);
    uint16_t raw_tmp = (uint16_t)(((uint16_t)data[2] << 8) | data[3]);

    *hum_pct = (float)raw_hum / 10.0f;

    /* Handle negative temperatures (MSB of temp byte is sign) */
    if (raw_tmp & 0x8000) {
        *temp_c = -(float)(raw_tmp & 0x7FFF) / 10.0f;
    } else {
        *temp_c = (float)raw_tmp / 10.0f;
    }

    return true;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    g_chip = gpiod_chip_open_by_name(chip_path);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", chip_path, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get lines */
    g_line_4 = gpiod_chip_get_line(g_chip, pin_4);
    if (!g_line_4) {
        fprintf(stderr, "Failed to get line %u: %s\n", pin_4, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_line_17 = gpiod_chip_get_line(g_chip, pin_17);
    if (!g_line_17) {
        fprintf(stderr, "Failed to get line %u: %s\n", pin_17, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting DHT22 readings on GPIO %u and GPIO %u.\n", pin_4, pin_17);

    for (int cycle = 0; cycle < NUM_CYCLES && g_running; cycle++) {
        float t4, h4, t17, h17;

        printf("\n--- Cycle %d/%d ---\n", cycle + 1, NUM_CYCLES);

        if (read_dht22(g_line_4, &t4, &h4)) {
            printf("GPIO %u: Temp=%.1f C, Hum=%.1f %%\n", pin_4, t4, h4);
        } else {
            fprintf(stderr, "Warning: failed to read DHT22 on GPIO %u\n", pin_4);
        }

        if (read_dht22(g_line_17, &t17, &h17)) {
            printf("GPIO %u: Temp=%.1f C, Hum=%.1f %%\n", pin_17, t17, h17);
        } else {
            fprintf(stderr, "Warning: failed to read DHT22 on GPIO %u\n", pin_17);
        }

        /* Sleep but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_PINS 5
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23};

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS] = {0, 0, 0, 0, 0};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, sighandler) == SIG_ERR ||
        signal(SIGTERM, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback for older kernels where gpiochip4 is not available */
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!chip) {
        chip = gpiod_chip_open_lookup("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all lines as outputs, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "blink", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting blink pattern on BCM pins 8, 9, 10, 11, 23.\n");

    for (int cycle = 0; cycle < 3 && keep_running; cycle++) {
        for (int bit = 0; bit < 8 && keep_running; bit++) {
            for (int i = 0; i < NUM_PINS; i++) {
                vals[i] ^= (bit & (1 << i)) ? 1 : 0;
            }
            for (int i = 0; i < NUM_PINS; i++) {
                if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                    fprintf(stderr, "Failed to set value on pin %u: %s\n",
                            pins[i], strerror(errno));
                    goto cleanup;
                }
            }
            usleep(100000); /* 100 ms per bit toggle */
        }
        if (cycle < 2) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIN_1 17
#define PIN_2 18
#define PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0)
    {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    int pins[3] = {PIN_1, PIN_2, PIN_3};
    const char *states[] = {"LOW", "HIGH"};

    while (running)
    {
        for (int i = 0; i < 3; ++i)
        {
            gpioSetMode(pins[i], PI_OUTPUT);
            gpioPWM(pins[i], (i % 2 == 0) ? 50 : 128);
            printf("GPIO %d set to %s\n", pins[i], states[i % 2]);
        }
        fflush(stdout);

        sleep(1);
    }

    /* Ensure outputs are left in a safe state before terminating */
    for (int i = 0; i < 3; ++i)
    {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

