#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip4"
#define LINE_OFFSET_1   16
#define LINE_OFFSET_2   20
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    while (keep_running) {
        static int val1 = 0;
        static int val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Failed to set value on line %d: %s\n",
                    LINE_OFFSET_2, strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d: %d | GPIO %d: %d\n", LINE_OFFSET_1, val1,
               LINE_OFFSET_2, val2);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 4000000
#define SPI_BITS_PER_WORD 8

static volatile sig_atomic_t g_running = 1;

static void int_handler(int signo) {
    (void)signo;
    g_running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Read one full-duplex transfer of 4 bytes.
     * MAX31855 returns:
     *   D[31..18] : 14-bit thermocouple temp (signed, 0.25 C/LSB)
     *   D[17]     : reserved
     *   D[16]     : fault bit
     *   D[15..4]  : 12-bit internal reference-junction temp (signed, 0.0625 C/LSB)
     */
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 4;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Check fault bit (D16) */
    if (rx[3] & 0x01) {
        fprintf(stderr, "MAX31855 fault detected (raw=0x%02X%02X%02X%02X)\n",
                rx[0], rx[1], rx[2], rx[3]);
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Thermocouple temperature: bits [31..18].
     * rx[0] = D[7..0], rx[1] = D[15..8] (upper 2 bits valid).
     * Signed 14-bit value in two's complement.
     */
    int16_t raw_tc = ((int16_t)(rx[1] << 8 | rx[0])) >> 2;

    /*
     * Internal reference junction: bits [15..4].
     * rx[2] = D[23..16], lower 4 bits valid.
     * Signed 12-bit value in two's complement.
     */
    int16_t raw_int = ((int16_t)(rx[2] << 8 | rx[3])) >> 4;

    float tc_temp = raw_tc * 0.25f;
    float int_temp = raw_int * 0.0625f;

    printf("Thermocouple Temperature: %.2f C\n", tc_temp);
    printf("Internal Reference Junction: %.2f C\n", int_temp);

    if (!g_running) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

