/*
 * HC-SR04 distance sensor reader using libgpiod.
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO 4
 *   ECHO -> GPIO 17 (3V3-safe via voltage divider recommended)
 *   VCC  -> 5V
 *   GND  -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#include <gpiod.h>

#define TRIGGER_PIN    4
#define ECHO_PIN       17

#define SPEED_OF_SOUND 34300.0   /* cm/s at ~20 °C */
#define TIMEOUT_US     30000     /* 30 ms timeout for echo pulse */
#define MAX_DISTANCE_CM 400.0   /* HC-SR04 rated max */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* Busy-wait for level on `line` with a microsecond timeout. Returns 0 on success, -1 on timeout. */
static int wait_level(struct gpiod_line *line, int level, long timeout_us)
{
    struct timespec deadline;
    clock_gettime(CLOCK_MONOTONIC, &deadline);
    const long end_ns = deadline.tv_nsec + (timeout_us % 1000000L) * 1000L;
    deadline.tv_sec += (end_ns / 1000000000L);
    deadline.tv_nsec = end_ns % 1000000000L;

    while (gpiod_line_get_value(line) != level) {
        if (!g_running)
            return -1;
        clock_gettime(CLOCK_MONOTONIC, &deadline);
        if (deadline.tv_sec == 0 && deadline.tv_nsec == 0)
            break; /* overflowed — treat as timeout */
    }
    return 0;
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(2);

    /* 10 µs trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to reset trigger: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (with timeout) */
    if (wait_level(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1.0;
    }

    struct timespec t_start;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    /* Wait for echo falling edge (with timeout) */
    if (wait_level(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1.0;
    }

    struct timespec t_end;
    clock_gettime(CLOCK_MONOTONIC, &t_end);

    double elapsed_s = (double)(t_end.tv_sec - t_start.tv_sec)
                     + (double)(t_end.tv_nsec - t_start.tv_nsec) / 1e9;

    double dist_cm = (elapsed_s * SPEED_OF_SOUND) / 2.0;

    if (dist_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm exceeds sensor range.\n", dist_cm);
        return -1.0;
    }
    return dist_cm;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("request trigger line as output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("request echo line as input");
        goto cleanup;
    }

    printf("HC-SR04 initialized on BCM GPIO %d (TRIG), %d (ECHO).\n",
           TRIGGER_PIN, ECHO_PIN);

    double dist = measure_distance(trig, echo);
    if (dist >= 0.0) {
        printf("Distance: %.2f cm\n", dist);
    } else {
        fprintf(stderr, "Measurement failed.\n");
    }

cleanup:
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define BCM_PIN        18
#define CONSUMER_NAME  "gpio18_output"

static volatile sig_atomic_t g_interrupted = 0;

static void signal_handler(int signum)
{
    (void)signum;
    g_interrupted = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Open the gpiochip that exposes BCM GPIO 18.
     * On Raspberry Pi OS the main gpiochip is usually /dev/gpiochip4
     * (the BCM2711 SoC). Fallback to /dev/gpiochip0 for older kernels.
     */
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open("/dev/gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open any gpiochip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                BCM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request exclusive output access to the line */
    ret = gpiod_line_request_output(line, CONSUMER_NAME, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                BCM_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply HIGH (1) to the pin */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d value: %s\n",
                BCM_PIN, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to HIGH\n", BCM_PIN);

    /* Release the line before exiting so the external circuit sees LOW */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x03

/* BMP280 Registers */
#define BMP280_REG_ID       0xD0
#define BMP280_REG_RESET    0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG   0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify chip ID */
    uint8_t id = 0;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Failed to read BMP280 ID register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != 0x58) {
        fprintf(stderr, "Unexpected BMP280 ID: 0x%02X (expected 0x58). Device not present?\n", id);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Soft reset */
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Failed to write soft-reset: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(2000);

    /* Config: t_sb=0.5ms(000), filter=off(000), spi3w_en=0 -> 0x00 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write config register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Ctrl_meas: osrs_t=x1(001), osrs_p=x1(001), mode=sleep(01) -> 0x25 */
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x25) < 0) {
        fprintf(stderr, "Failed to write ctrl_meas register: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BMP280 initialized successfully.\n");

    for (int i = 0; i < 3 && g_running; ++i) {
        uint8_t data[6];
        if (i2c_read_burst(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
            fprintf(stderr, "Failed to read pressure/temp data: %s\n", strerror(errno));
            break;
        }

        int32_t raw_pressure = ((int32_t)data[0] << 12) |
                               ((int32_t)data[1] << 4) |
                               ((int32_t)data[2] >> 4);
        int32_t raw_temperature = ((int32_t)data[3] << 12) |
                                  ((int32_t)data[4] << 4) |
                                  ((int32_t)data[5] >> 4);

        float temperature = (float)((double)raw_temperature / 16384.0);
        float pressure = (float)((double)raw_pressure / 16384.0);

        printf("Reading %d:\n", i + 1);
        printf("  Temperature: %.2f °C\n", temperature);
        printf("  Pressure: %.2f hPa\n", pressure);
        fflush(stdout);

        /* Wait for next conversion cycle (~500ms) */
        usleep(500000);
    }

    if (!g_running) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

