#define CHIP_NAME "gpiochip0"
#define NUM_PINS 4

static const unsigned int pins[NUM_PINS] = {17, 22, 23, 24};
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    bool lines_requested = false;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    if (gpiod_request_lines(lines, &NUM_PINS, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Failed to request lines as outputs");
        goto cleanup;
    }
    lines_requested = true;

    // Apply alternating states: HIGH, LOW, HIGH, LOW
    int values[NUM_PINS] = {1, 0, 1, 0};

    for (int i = 0; i < NUM_PINS && keep_running; i++) {
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            perror("Failed to set value");
            goto cleanup;
        }
        printf("GPIO %u set to %s\n", pins[i], values[i] ? "HIGH" : "LOW");
    }

    if (!keep_running) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    } else {
        printf("Values applied successfully.\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (lines_requested) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

