    return (n == (ssize_t)len) ? 0 : -1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, bme280_calib_data *cal) {
    uint8_t buf[26];
    if (i2c_read_reg(fd, 0x88, buf, 26) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    cal->dig_H1 = buf[25];

    uint8_t hbuf[7];
    if (i2c_read_reg(fd, 0xE1, hbuf, 7) < 0) return -1;
    cal->dig_H2 = (int16_t)(hbuf[0] | (hbuf[1] << 8));
    cal->dig_H3 = hbuf[2];
    cal->dig_H4 = (int16_t)((hbuf[3] << 4) | (hbuf[4] & 0x0F));
    cal->dig_H5 = (int16_t)((hbuf[5] << 4) | ((hbuf[4] >> 4) & 0x0F));
    cal->dig_H6 = (int8_t)hbuf[6];
    return 0;
}

static int bme280_init(int fd, bme280_calib_data *cal) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60).\n", id);
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) < 0) return -1;
    usleep(2000);

    while (1) {
        uint8_t status;
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status, 1) < 0) return -1;
        if (!(status & 0x01)) break;
        usleep(2000);
    }

    if (read_calibration(fd, cal) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bme280_read_raw(int fd, int32_t *temp, int32_t *press, int32_t *hum) {
    uint8_t d[8];
    if (i2c_read_reg(fd, BME280_REG_DATA, d, 8) < 0) return -1;
    *press = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4);
    *temp  = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4);
    *hum   = (d[6] << 8)  | d[7];
    return 0;
}

static void sleep_sec(unsigned int sec) {
    unsigned int remaining = sec;
    while (remaining > 0 && g_running) {
        remaining = sleep(remaining);
    }
}

int main(void) {
    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sighandler);
    signal(SIGTERM, sighandler);

    bme280_calib_data cal;
    if (bme280_init(fd, &cal) < 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BME280 initialized successfully.\n");

    for (int i = 0; i < 3 && g_running; i++) {
        int32_t raw_p, raw_t, raw_h;
        if (bme280_read_raw(fd, &raw_t, &raw_p, &raw_h) < 0) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            break;
        }

        /* Temperature compensation (simplified) */
        double t_fine = ((double)raw_t / 16384.0 - (double)cal.dig_T1 / 1024.0)
                      * (double)cal.dig_T2;
        double T = t_fine + (((double)raw_t / 131072.0 - (double)cal.dig_T1 / 8192.0)
                            * (double)cal.dig_T3) / 64.0;

        /* Pressure compensation (simplified) */
        double P = (t_fine / 5120.0 * (double)cal.dig_P1)
                 + (t_fine / 524288.0 * (double)cal.dig_P2)
                 + (t_fine / 131072.0 * (double)cal.dig_P3)
                 + (t_fine / 2097152.0 * (double)cal.dig_P4)
                 + (t_fine / 8388608.0 * (double)cal.dig_P5)
                 + (t_fine / 33554432.0 * (double)cal.dig_P6)
                 + (t_fine / 134217728.0 * (double)cal.dig_P7)
                 + (t_fine / 536870912.0 * (double)cal.dig_P8)
                 + (t_fine / 2147483648.0 * (double)cal.dig_P9);

        /* Humidity compensation (simplified) */
        double H = (double)raw_h / 16384.0 * (double)cal.dig_H1
                  + (double)raw_h / 1048576.0 * (double)cal.dig_H2
                  + (double)raw_h / 1048576.0 * (double)cal.dig_H3
                  + (double)raw_h / 1048576.0 * (double)cal.dig_H4
                  + (double)raw_h / 1048576.0 * (double)cal.dig_H5
                  + (double)raw_h / 1048576.0 * (double)cal.dig_H6;

        printf("Reading %d:\n", i + 1);
        printf("  Temperature: %.2f °C\n", T);
        printf("  Pressure: %.2f Pa\n", P);
        printf("  Humidity: %.2f %%RH\n", H);
        fflush(stdout);

        sleep_sec(5);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET     17          /* BCM pin 17 */
#define POLL_INTERVAL   1           /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers so Ctrl-C / SIGTERM clean up properly. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital_out", 0) < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n",
                LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int val = rand() % 2;
        if (gpiod_line_set_value(line, val) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", LINE_OFFSET, val);
        fflush(stdout);

        /* Sleep in 1-second chunks so signals are caught promptly. */
        unsigned int remaining = POLL_INTERVAL;
        while (remaining > 0 && g_running) {
            remaining = sleep(remaining);
        }
    }

    /* Ensure the line is left low before releasing. */
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Warning: failed to reset line on exit: %s\n",
                strerror(errno));
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE   B9600

static volatile sig_atomic_t g_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", SERIAL_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Clear O_NDELAY so reads block (we use VMIN/VTIME). */
    if (fcntl(fd, F_SETFL, 0) == -1) {
        perror("fcntl F_SETFL");
        close(fd);
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial communication initialized on %s at 9600 baud.\n", SERIAL_PORT);
    fflush(stdout);

    char buffer[256];
    ssize_t nread;

    while (g_running) {
        nread = read(fd, buffer, sizeof(buffer) - 1);
        if (nread > 0) {
            buffer[nread] = '\0';
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (nread == -1 && errno == EAGAIN) {
            /* Timeout — no data available this cycle. */
        } else if (nread == -1) {
            perror("read");
            break;
        }
        usleep(100000); /* 0.1 s */
    }

    if (close(fd) == -1) {
        perror("close");
        return EXIT_FAILURE;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

/*
 * HC-SR04 distance sensor reader using libgpiod.
 *
 * Wiring (Raspberry Pi 40-pin header):
 *   TRIG -> BCM 17 (physical pin 11)
 *   ECHO -> BCM 18 (physical pin 12) [via voltage divider if echo is 5 V]
 *   VCC  -> 5 V (pin 2/4)
 *   GND  -> GND (pin 6/9/14/20/30/34/36/38/40)
 *
 * Build: gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN	17
#define ECHO_PIN	18

/* Speed of sound at ~20 °C sea-level: 343 m/s = 0.0343 cm/us */
#define SOUND_SPEED_CM_PER_US	0.0343

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signum)
{
    (void)signum;
    g_running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

/*
 * Wait for ECHO to reach target level while timing out after `timeout_us`.
 * Returns true if the target was reached, false otherwise.
 */
static bool wait_level(struct gpiod_line *echo, int target,
                        long long start_us, long long timeout_us)
{
    const long long deadline = start_us + timeout_us;
    for (;;) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return false;
        }
        if (val == target)
            return true;
        if (now_us() >= deadline)
            return false;
    }
}

/*
 * Trigger a single measurement and read the pulse width in microseconds.
 * Returns -1 on error or if the sensor did not respond within TIMEOUT_US.
 */
static long long measure_pulse_width(struct gpiod_line *trig,
                                     struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "set trigger high failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low (after pulse) failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (max 30 ms round trip) */
    if (!wait_level(echo, 1, now_us(), 30000)) {
        fprintf(stderr, "Timeout waiting for echo rising edge.\n");
        return -1;
    }

    long long rise = now_us();

    /* Wait for echo falling edge (max 30 ms round trip) */
    if (!wait_level(echo, 0, rise, 30000)) {
        fprintf(stderr, "Timeout waiting for echo falling edge.\n");
        return -1;
    }

    return now_us() - rise;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        goto cleanup;
    }

    /* Open gpiochip0 (the main character device on RPi 40-pin header) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value LOW */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Request trigger line as output failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Request echo line as input failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ready. Press Ctrl+C to stop.\n");

    while (g_running) {
        long long pw = measure_pulse_width(trig, echo);

        if (pw < 0) {
            fprintf(stderr, "Measurement failed.\n");
        } else {
            double dist_cm = (double)pw * SOUND_SPEED_CM_PER_US / 2.0;
            printf("Distance: %.2f cm (%lld us)\n", dist_cm, pw);
        }

        /* Sleep 0.5 s but wake early on signal */
        for (int i = 0; i < 5 && g_running; i++)
            usleep(100000);
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip4"
#define LINE_OFFSET 8

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    if (signal(SIGINT, intHandler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output with initial low state
    ret = gpiod_line_request_output(line, "output_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting loop...\n");

    while (keep_running) {
        // Toggle the value
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading line value: %s\n", strerror(errno));
            break;
        }
        int new_value = !current_value;

        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Error setting line value: %s\n", strerror(errno));
            break;
        }

        printf("Output set to: %d\n", new_value);

        usleep(1000); // Sleep for 1ms
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53

int main() {
    int file;
    char filename[20];
    uint8_t reg = 0x0B; // Register to read data from
    uint8_t buf[6];     // Buffer to store raw data
    int16_t x, y, z;

    // Open I2C device
    snprintf(filename, 19, "/dev/i2c-1");
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(file, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return 1;
    }

    // Read 6 bytes of data starting from register 0x0B
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write register address");
        close(file);
        return 1;
    }

    if (read(file, buf, 6) != 6) {
        perror("Failed to read data");
        close(file);
        return 1;
    }

    // Convert raw data to signed integers
    x = (buf[0] << 8) | buf[1];
    y = (buf[2] << 8) | buf[3];
    z = (buf[4] << 8) | buf[5];

    // Print the results
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(file);
    return 0;
}

