        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "blink", 0) < 0) {
            fprintf(stderr, "Error requesting line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        values[i] = 0;
    }

    /* Main loop: toggle each pin and print its new value */
    while (keep_running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Error setting line %u: %s\n",
                        pins[i], strerror(errno));
                goto cleanup;
            }
            printf("GPIO %u: %d\n", pins[i], values[i]);
        }
        fflush(stdout);

        /* Sleep 0.05 s; break early if interrupted */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 50000000 };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release all acquired lines */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

