#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN      18   /* BCM pin number */
#define DUTY_CYCLE   500  /* 0..1000 -> 0%..100% duty cycle */
#define STEP_DELAY_S 0.1  /* seconds between steps */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler.\n");
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Set PWM frequency to 1 kHz (default 25 kHz may be too high for some
     * LED loads). Range is 0..1000 by default.
     */
    if (gpioSetPWMfrequency(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, 1000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (gpioPWM(PWM_PIN, DUTY_CYCLE) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d, %d) failed.\n",
                    PWM_PIN, DUTY_CYCLE);
            break;
        }
        printf("GPIO %d PWM set to %d\n", PWM_PIN, DUTY_CYCLE);
        fflush(stdout);

        time_sleep(STEP_DELAY_S);
    }

    /* Clean up: turn off PWM and release the pin */
    gpioPWM(PWM_PIN, 0);
    gpioSetMode(PWM_PIN, PI_INPUT);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define LINE_1   4
#define LINE_2   17
#define CYCLES   5

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, sighandler) == SIG_ERR ||
        signal(SIGTERM, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("Starting %d cycles of alternating output states...\n", CYCLES);

    for (int i = 0; i < CYCLES && keep_running; i++) {
        int v1 = i % 2 ? 1 : 0;
        int v2 = i % 2 ? 0 : 1;

        if (gpiod_line_set_value(line1, v1) < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", LINE_1, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, v2) < 0) {
            fprintf(stderr, "Failed to set line %d: %s\n", LINE_2, strerror(errno));
            goto cleanup;
        }

        printf("Cycle %d: Line %d=%d, Line %d=%d\n",
               i + 1, LINE_1, v1, LINE_2, v2);

        /* Sleep 1 second between cycles, but wake early on signal */
        for (int s = 0; s < 1 && keep_running; s++)
            sleep(1);
    }

    if (!keep_running)
        printf("\nInterrupted by signal.\n");

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip; gpiod handles null safety internally */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

