    // Get the line for BCM pin 23
    line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Request the line as output, initially low
    if (gpiod_line_request_output(line, "output_example", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    // Toggle the output: HIGH then LOW
    printf("Setting GPIO %d HIGH\n", OUTPUT_PIN);
    fflush(stdout);
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set value HIGH");
        goto cleanup;
    }
    sleep(1);

    printf("Setting GPIO %d LOW\n", OUTPUT_PIN);
    fflush(stdout);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set value LOW");
        goto cleanup;
    }
    sleep(1);

    ret = EXIT_SUCCESS;

cleanup:
    // Release the line and close the chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip4"
#define LINE_OFFSET_1   17
#define LINE_OFFSET_2   27
#define POLL_INTERVAL_US 200000

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", LINE_OFFSET_1, LINE_OFFSET_2);

    while (keep_running) {
        static int val1 = 0, val2 = 0;

        val1 = !val1;
        val2 = !val2;

        if (gpiod_line_set_value(line1, val1) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_1, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, val2) < 0) {
            fprintf(stderr, "Error setting value on line %d: %s\n",
                    LINE_OFFSET_2, strerror(errno));
            goto cleanup;
        }

        printf("Line %d: %d | Line %d: %d\n", LINE_OFFSET_1, val1,
               LINE_OFFSET_2, val2);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on any exit path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

