#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PIN_1 18
#define PIN_2 21
#define PIN_3 22

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers.\n");
    }

    int pins[] = {PIN_1, PIN_2, PIN_3};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    /* Set each pin as a hardware-PWM-capable output */
    for (int i = 0; i < num_pins; ++i) {
        gpioSetMode(pins[i], PI_OUTPUT);
        if (gpioHardwarePWM(pins[i], 1000, 500000) != 0) {
            fprintf(stderr, "Error: failed to start PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM started on GPIO %d, %d, %d at 1 kHz, 50%% duty cycle.\n",
           PIN_1, PIN_2, PIN_3);

    /* Keep running until interrupted */
    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown: turn off PWM and restore input mode */
    for (int i = 0; i < num_pins; ++i) {
        gpioHardwarePWM(pins[i], 0, 0);   /* stop PWM */
        gpioSetMode(pins[i], PI_INPUT);   /* safe default */
    }

    gpioTerminate();
    printf("\nPWM stopped and GPIO released.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 7

static const unsigned int pins[NUM_PINS] = {17, 18, 22, 23, 24, 25, 27};

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret;

    /* Open the gpiochip that exposes BCM GPIOs on the Raspberry Pi */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as an output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "digital_out", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        values[i] = 0;
    }

    /* Apply alternating states to each pin */
    for (int i = 0; i < NUM_PINS; i++) {
        values[i] = (i % 2 == 0) ? 1 : 0;
        ret = gpiod_line_set_value(lines[i], values[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to set value on line %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Print the final state of each pin */
    printf("GPIO States:\n");
    for (int i = 0; i < NUM_PINS; i++)
        printf("GPIO %u: %d\n", pins[i], values[i]);

    /* Release lines before exiting */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define TIMEOUT_US  30000   /* 30 ms timeout for echo */
#define POLL_MS     100

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("request trigger line as output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("request echo line as input");
        goto cleanup;
    }

    printf("HC-SR04 monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }
        usleep(2);

        /* Send 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("set trigger high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low after pulse");
            break;
        }

        /* Wait for echo rising edge (timeout) */
        long t_start = 0;
        int seen_rising = 0;
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo line");
                goto loop_done;
            }
            if (!t_start) t_start = (long)clock();
        } while (val == 0 && (clock() - t_start) * 1000L / CLOCKS_PER_SEC < TIMEOUT_US);

        if (!seen_rising) {
            fprintf(stderr, "Warning: Echo pin did not go high (sensor absent or not responding)\n");
            goto loop_done;
        }

        /* Measure echo pulse width (rising -> falling) */
        long t_rise = (long)clock();
        int seen_falling = 0;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo line during fall");
                goto loop_done;
            }
            if (!seen_falling && val == 0) seen_falling = 1;
        } while (val == 1 && (clock() - t_rise) * 1000L / CLOCKS_PER_SEC < TIMEOUT_US);

        if (!seen_falling) {
            fprintf(stderr, "Warning: Echo pin did not go low (stuck high?)\n");
            goto loop_done;
        }

        long elapsed_us = (clock() - t_rise) * 1000L / CLOCKS_PER_SEC;
        float distance_cm = (float)elapsed_us * 0.0343f / 2.0f;

        if (distance_cm > 400.0f || distance_cm < 2.0f) {
            fprintf(stderr, "Warning: Distance out of valid range (%.2f cm)\n", distance_cm);
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
        }

loop_done:
        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN      16   /* BCM pin number */
#define PWM_FREQ     1000 /* Hz */
#define DUTY_CYCLE   500  /* range 0..range; 50% of 255 */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int rc = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed (%d)\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    if (rc < 0) {
        fprintf(stderr, "Warning: gpioSetPWMfrequency(%d) returned %d\n", PWM_PIN, rc);
    }

    rc = gpioSetPWMrange(PWM_PIN, 255);
    if (rc != 0) {
        fprintf(stderr, "Warning: gpioSetPWMrange(%d) returned %d\n", PWM_PIN, rc);
    }

    rc = gpioPWM(PWM_PIN, DUTY_CYCLE);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed (%d)\n", PWM_PIN, DUTY_CYCLE, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM duty cycle set to %d/255 on BCM GPIO %d at %d Hz.\n",
           DUTY_CYCLE, PWM_PIN, PWM_FREQ);

    while (g_running) {
        pause(); /* wake on signal */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE   0x80
#define TCS34725_ATIME    0x81
#define TCS34725_CDATAL   0x94
#define TCS34725_CDATAH   0x95
#define TCS34725_RDATAL   0x96
#define TCS34725_RDATAH   0x97
#define TCS34725_GDATAL   0x98
#define TCS34725_GDATAH   0x99
#define TCS34725_BDATAL   0x9A
#define TCS34725_BDATAH   0x9B

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int tcs34725_init(int fd) {
    /* Power ON + RGBC enable */
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: failed to write ENABLE register: %s\n", strerror(errno));
        return -1;
    }
    /* Set integration time to 2.4ms (ATIME=0xFF) */
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error: failed to write ATIME register: %s\n", strerror(errno));
        return -1;
    }
    usleep(3000);
    return 0;
}

static int read_color_data(int fd, uint16_t *clear, uint16_t *red,
                           uint16_t *green, uint16_t *blue) {
    uint8_t lo, hi;

    if (i2c_read_reg8(fd, TCS34725_CDATAL, &lo) < 0 || i2c_read_reg8(fd, TCS34725_CDATAH, &hi) < 0) {
        fprintf(stderr, "Error: failed to read clear data: %s\n", strerror(errno));
        return -1;
    }
    *clear = ((uint16_t)hi << 8) | lo;

    if (i2c_read_reg8(fd, TCS34725_RDATAL, &lo) < 0 || i2c_read_reg8(fd, TCS34725_RDATAH, &hi) < 0) {
        fprintf(stderr, "Error: failed to read red data: %s\n", strerror(errno));
        return -1;
    }
    *red = ((uint16_t)hi << 8) | lo;

    if (i2c_read_reg8(fd, TCS34725_GDATAL, &lo) < 0 || i2c_read_reg8(fd, TCS34725_GDATAH, &hi) < 0) {
        fprintf(stderr, "Error: failed to read green data: %s\n", strerror(errno));
        return -1;
    }
    *green = ((uint16_t)hi << 8) | lo;

    if (i2c_read_reg8(fd, TCS34725_BDATAL, &lo) < 0 || i2c_read_reg8(fd, TCS34725_BDATAH, &hi) < 0) {
        fprintf(stderr, "Error: failed to read blue data: %s\n", strerror(errno));
        return -1;
    }
    *blue = ((uint16_t)hi << 8) | lo;

    return 0;
}

int main(void) {
    const char *device = "/dev/i2c-1";
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        goto cleanup;
    }

    fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        goto cleanup;
    }

    /* Quick presence probe by touching ENABLE register */
    uint8_t dummy;
    if (i2c_read_reg8(fd, TCS34725_ENABLE, &dummy) < 0) {
        fprintf(stderr, "Error: no TCS34725 found at 0x%02X (%s).\n",
                TCS34725_ADDRESS, strerror(errno));
        goto cleanup;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725.\n");
        goto cleanup;
    }

    printf("TCS34725 initialized successfully.\n");

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (read_color_data(fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear=%u Red=%u Green=%u Blue=%u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read color data.\n");
        }

        /* Sleep 0.5 s but wake early on signal */
        for (int i = 0; i < 5 && g_running; i++)
            usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

