#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 7

static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 23, 24, 27};

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS] = {0, 1, 0, 1, 0, 1, 0};
    int ret = EXIT_FAILURE;

    // Set up signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip 0 (default for Raspberry Pi)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines and configure as outputs with initial states
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio_control", values[i]) < 0) {
            fprintf(stderr, "Failed to request output on pin %u\n", pins[i]);
            goto cleanup;
        }
    }

    // Print initial states
    printf("Initial States:\n");
    for (int i = 0; i < NUM_PINS; i++) {
        printf("GPIO %u: %d\n", pins[i], values[i]);
    }
    fflush(stdout);

    // Sleep for 5 seconds, checking for signals
    for (int i = 0; i < 5 && keep_running; i++) {
        sleep(1);
    }

    // Read back and print final states
    printf("\nFinal States:\n");
    for (int i = 0; i < NUM_PINS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Warning: Failed to read GPIO %u\n", pins[i]);
            val = values[i]; // use last known value as fallback
        }
        printf("GPIO %u: %d\n", pins[i], val);
        values[i] = val; // update stored value
    }
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    // Release lines and close chip
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

