#define PIN_1 2
#define PIN_2 3
#define PIN_3 18

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device not present?)\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PIN_1, PIN_2, PIN_3};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    /* Configure each pin as hardware-PWM-capable output */
    for (int i = 0; i < num_pins; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* Start with duty cycle 0% */
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d) initial set failed\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins && running; ++i) {
            int val = (i % 2 == 0) ? 255 : 0;
            if (gpioPWM(pins[i], val) != 0) {
                fprintf(stderr, "Warning: gpioPWM(%d) update failed\n", pins[i]);
            } else {
                printf("GPIO %d -> %s\n", pins[i],
                       val > 0 ? "HIGH" : "LOW");
            }
        }
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < 5 && running; ++s) {
            sleep(1);
        }
    }

    /* Clean up: turn off outputs and release pigpio resources */
    for (int i = 0; i < num_pins; ++i) {
        gpioPWM(pins[i], 0);
        gpioSetMode(pins[i], PI_INPUT);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

