        signal(SIGTERM, int_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, LINE_1);
    if (!line1) {
        perror("gpiod_chip_get_line(6)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_2);
    if (!line2) {
        perror("gpiod_chip_get_line(23)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "output-demo", 0) < 0) {
        perror("gpiod_line_request_output(6)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "output-demo", 0) < 0) {
