        perror("gpiod_line_set_value(6)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 1) < 0) {
        perror("gpiod_line_set_value(23)");
        goto cleanup;
    }

    printf("GPIO %d: HIGH\n", LINE_1);
    printf("GPIO %d: HIGH\n", LINE_2);
    fflush(stdout);

