#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_stop = 1;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening /dev/ttyAMA0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Clear O_NDELAY so reads block by default */
    if (fcntl(fd, F_SETFL, 0) == -1) {
        perror("fcntl F_SETFL");
        close(fd);
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Serial communication initialized on /dev/ttyAMA0 at 9600 baud.\n");

    while (!g_stop) {
        char buf[256];
        ssize_t n = read(fd, buf, sizeof(buf));

        if (n > 0) {
            for (ssize_t i = 0; i < n; i++) {
                putchar((unsigned char)buf[i]);
            }
            fflush(stdout);
        } else if (n == 0) {
            usleep(100000);
        } else {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(100000);
            } else {
                fprintf(stderr, "read error: %s\n", strerror(errno));
                break;
            }
        }
    }

    printf("\nExiting...\n");
    tcflush(fd, TCIOFLUSH);
    close(fd);
    return EXIT_SUCCESS;
}

