/*
 * HC-SR04 distance sensor reader using libgpiod.
 *
 * Wiring (BCM numbering):
 *   TRIG -> GPIO 18
 *   ECHO -> GPIO 23 (use a voltage divider if the module is 5 V)
 *   VCC  -> 5 V, GND -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>

#define TRIGGER_PIN    18
#define ECHO_PIN       23

/* Speed of sound at 20 °C / 68 °F ≈ 343 m/s = 0.0343 cm/us */
#define SPEED_OF_SOUND 0.0343

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signum)
{
    (void)signum;
    g_running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void)
{
    /* Graceful shutdown on Ctrl-C / SIGTERM */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *chipname = "gpiochip4"; /* BCM GPIO bank on Pi 5 */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        chip = gpiod_chip_open_by_label(chipname);
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(4);
    }
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Request trigger line failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Request echo line failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /*
     * Ensure TRIG starts low. A brief pulse (~10 us) triggers a single
     * measurement cycle. Allow time for the sensor to settle after power-up.
     */
    usleep(50000);

    int ret = EXIT_SUCCESS;

    while (g_running) {
        /* Issue 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Set trig high failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Set trig low failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        /* Wait for echo rising edge (timeout ~50 ms — out of range) */
        long long t_start = now_us();
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Read echo high failed: %s\n", strerror(errno));
                ret = EXIT_FAILURE;
                goto cleanup;
            }
            if (!g_running) break;
        } while (val == 0 && (now_us() - t_start) < 50000);

        if (!g_running) break;
        if (val < 0) {
            ret = EXIT_FAILURE;
            break;
        }
        if (val == 0) {
            fprintf(stderr, "Timeout waiting for echo start.\n");
            continue;
        }

        /* Measure echo pulse width (rising -> falling) */
        long long rise = now_us();
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Read echo low failed: %s\n", strerror(errno));
                ret = EXIT_FAILURE;
                goto cleanup;
            }
            if (!g_running) break;
        } while (val == 1 && (now_us() - rise) < 30000);

        if (!g_running) break;
        if (val < 0) {
            ret = EXIT_FAILURE;
            break;
        }
        if (val == 1) {
            fprintf(stderr, "Timeout waiting for echo end.\n");
            continue;
        }

        long long fall = now_us();
        long long elapsed = fall - rise;

        double distance_cm = (elapsed * SPEED_OF_SOUND) / 2.0;

        printf("Distance: %.2f cm\n", distance_cm);
        fflush(stdout);

        /* Small gap between measurements (> 60 ms per datasheet) */
        usleep(70000);
    }

cleanup:
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE     18          /* BCM pin 18 */
#define CONSUMER        "output-set"

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_stop = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, OUTPUT_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", OUTPUT_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                OUTPUT_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Apply HIGH to the output */
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set value on line %d: %s\n",
                OUTPUT_LINE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Output set to HIGH on GPIO %d\n", OUTPUT_LINE);

    /* Release the line before exiting so the consumer is unregistered */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN      18   /* BCM pin number */
#define PWM_FREQ_HZ  1000 /* 1 kHz carrier            */
#define DUTY_CYCLE   500  /* 50% of range 0-1000     */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    int rc;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio daemon/library support --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /*
     * Set up hardware PWM on BCM 18.
     *
     * gpioHardwarePWM() configures the hardware PWM peripheral directly:
     *   duty_cycle in microseconds per period (range 0-1,000,000).
     *   frequency in Hz.
     *
     * A value of 0 for duty_cycle produces a logic LOW; any other value
     * produces a square wave at the given frequency.
     */
    rc = gpioHardwarePWM(PWM_PIN, PWM_FREQ_HZ, DUTY_CYCLE);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM(%d, %d, %d) failed (code %d).\n",
                PWM_PIN, PWM_FREQ_HZ, DUTY_CYCLE, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on BCM GPIO %d @ %d Hz, duty=%u us.\n",
           PWM_PIN, PWM_FREQ_HZ, (unsigned)DUTY_CYCLE);

    /* --- Main loop: report state and wait for signal --- */
    while (g_running) {
        printf("State: BCM GPIO %d = %s\n", PWM_PIN,
               (DUTY_CYCLE == 0) ? "LOW" : "HIGH");
        fflush(stdout);

        /* Sleep 0.2 s but wake promptly on signal */
        time_sleep(0.2);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");

    /* Stop PWM output before terminating */
    rc = gpioHardwarePWM(PWM_PIN, 0, 0);
    if (rc != 0) {
        fprintf(stderr, "Warning: gpioHardwarePWM stop failed (code %d).\n", rc);
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define LINE_OFFSET_1   17
#define LINE_OFFSET_2   18

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int signo)
{
    (void)signo;
    g_stop = 1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, sighandler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, LINE_OFFSET_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, LINE_OFFSET_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital_out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Toggle each line independently and report state */
    printf("Applying HIGH to GPIO %d, LOW to GPIO %d\n", LINE_OFFSET_1, LINE_OFFSET_2);
    fflush(stdout);

    if (gpiod_line_set_value(line1, 1) < 0) {
        fprintf(stderr, "Failed to set line %d high: %s\n", LINE_OFFSET_1, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_set_value(line2, 0) < 0) {
        fprintf(stderr, "Failed to set line %d low: %s\n", LINE_OFFSET_2, strerror(errno));
        goto cleanup;
    }

    /* Wait briefly so the output is visible before exiting */
    sleep(1);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip cleanly */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CHIP_NAME       "gpiochip0"
#define OUTPUT_LINE_1   18
#define OUTPUT_LINE_2   23
#define OUTPUT_LINE_3   24
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_LINE_1);
    line2 = gpiod_chip_get_line(chip, OUTPUT_LINE_2);
    line3 = gpiod_chip_get_line(chip, OUTPUT_LINE_3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to acquire one or more lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "output-ctrl", 0) < 0 ||
        gpiod_line_request_output(line2, "output-ctrl", 0) < 0 ||
        gpiod_line_request_output(line3, "output-ctrl", 0) < 0) {
        fprintf(stderr, "Failed to request output direction: %s\n", strerror(errno));
        goto cleanup;
    }

    while (keep_running) {
        static int states[3] = {0, 0, 0};
        int vals[3];

        for (int i = 0; i < 3; i++) {
            vals[i] = states[i];
            states[i] = !states[i];          /* toggle each channel */
        }

        if (gpiod_line_set_value(line1, vals[0]) < 0 ||
            gpiod_line_set_value(line2, vals[1]) < 0 ||
            gpiod_line_set_value(line3, vals[2]) < 0) {
            fprintf(stderr, "Failed to set output values: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO%d=%d, GPIO%d=%d, GPIO%d=%d\n",
               OUTPUT_LINE_1, vals[0],
               OUTPUT_LINE_2, vals[1],
               OUTPUT_LINE_3, vals[2]);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

// Register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

void intHandler(int dummy) {
    (void)dummy;
    running = 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = intHandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    const char *i2c_dev = "/dev/i2c-1";
    int fd = open(i2c_dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    // Wake up the MPU6050 (clear sleep bit)
    uint8_t pwr_mgmt_buf[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, pwr_mgmt_buf, 2) != 2) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); // 100ms delay for stabilization

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
            break;
        }

        uint8_t buf[6];
        ssize_t bytes_read = read(fd, buf, 6);
        if (bytes_read != 6) {
            fprintf(stderr, "Error reading data (expected 6 bytes, got %zd): %s\n", bytes_read, strerror(errno));
            break;
        }

        int16_t accel_x = (buf[0] << 8) | buf[1];
        int16_t accel_y = (buf[2] << 8) | buf[3];
        int16_t accel_z = (buf[4] << 8) | buf[5];

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        sleep(1);
    }

    close(fd);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17

static volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    (void)dummy;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    if (signal(SIGINT, intHandler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output with initial low state
    ret = gpiod_line_request_output(line, "blink", 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO %d...\n", GPIO_LINE_OFFSET);

    while (keep_running) {
        // Toggle state
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read GPIO value: %s\n", strerror(errno));
            break;
        }
        int new_value = !current_value;

        ret = gpiod_line_set_value(line, new_value);
        if (ret != 0) {
            fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, new_value);

        sleep(0.6);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}
